window.FG_SHARED_KNOWLEDGE=[{"kind":"article","id":"100-prozent-finanzierung","title":"100-Prozent-Finanzierung","category":"Finanzierung","summary":"100 % Finanzierung bedeutet in der üblichen Marktlogik: der Kaufpreis wird vollständig finanziert; die Erwerbsnebenkosten werden regelmäßig aus Eigenmitteln getragen.","answer":"Eine 100-%-Finanzierung finanziert typischerweise den Kaufpreis, nicht automatisch die Nebenkosten. Gegenüber 80–90 % Finanzierung kann der Zinssatz höher liegen, weil der Beleihungsauslauf steigt. Bei 400.000 € Kaufpreis und 40.000 € Nebenkosten wären für eine klassische 100-%-Struktur etwa 40.000 € Eigenmittel für die Nebenkosten nötig. Entscheidungsrelevant: 100 % Kaufpreisfinanzierung kann sinnvoll sein, wenn Einkommen und Bonität stark sind und Eigenkapital bewusst als Reserve oder für andere Zwecke gehalten wird. Die Mehrzinsen müssen gegen den Nutzen der erhaltenen Liquidität gerechnet werden.","url":"/wissen/100-prozent-finanzierung/","keywords":["100-prozent-finanzierung","100","finanzierung","bedeutet","üblichen","marktlogik","kaufpreis","vollständig","finanziert","erwerbsnebenkosten","regelmäßig","aus","eigenmitteln","getragen.","100-%-finanzierung","entspricht","darlehen","ungefähr","kaufpreis.","grunderwerbsteuer","notar/grundbuch","gegebenenfalls","courtage","davon","unterscheiden","häufig","eigenkapital","bezahlt.","typischerweise","automatisch","nebenkosten.","gegenüber","kann","zinssatz","höher","liegen","weil","beleihungsauslauf","steigt.","400.000","40.000","nebenkosten","wären","klassische","100-%-struktur","etwa","eigenmittel","nötig.","entscheidungsrelevant","kaufpreisfinanzierung","sinnvoll","sein","wenn","einkommen","bonität","stark","bewusst","reserve","andere","zwecke"]},{"kind":"article","id":"110-prozent-finanzierung","title":"110-Prozent-Finanzierung","category":"Finanzierung","summary":"Eine 110-%-Finanzierung finanziert Kaufpreis und Erwerbsnebenkosten. Sie erhöht Darlehenssumme, Beleihungsrisiko und häufig auch den Zinssatz.","answer":"Bei einer 110-%-Finanzierung werden Kaufpreis und Erwerbsnebenkosten weitgehend fremdfinanziert. Das erhöht nicht nur das Darlehen, sondern meist auch den Beleihungsauslauf und damit die Kondition. Ein Zinsaufschlag von einigen Zehntelprozentpunkten gegenüber einer niedrigeren Finanzierung ist am Markt möglich, aber nicht garantiert oder gesetzlich festgelegt. Beispiel: 440.000 € Darlehen zu 4,5 % plus 2 % Tilgung ergeben rund 2.383 € Monatsrate; 380.000 € zu 3,8 % plus 2 % Tilgung rund 1.837 €. Entscheidungsrelevant: 110 % Finanzierung nur wählen, wenn der Haushaltsüberschuss auch bei höherem Anschlusszins trägt und zusätzlich eine Liquiditätsreserve für Instandhaltung, Leerstand oder Sonderumlagen vorhanden ist.","url":"/wissen/110-prozent-finanzierung/","keywords":["110-prozent-finanzierung","110-%-finanzierung","finanziert","kaufpreis","erwerbsnebenkosten.","sie","erhöht","darlehenssumme","beleihungsrisiko","häufig","zinssatz.","liegt","über","weil","zusätzlich","grunderwerbsteuer","notar/grundbuch","gegebenenfalls","courtage","fremdfinanziert","werden.","bezeichnung","110","marktbezeichnung","tatsächliche","quote","hängt","höhe","nebenkosten","ab.","erwerbsnebenkosten","weitgehend","fremdfinanziert.","darlehen","sondern","meist","beleihungsauslauf","damit","kondition.","zinsaufschlag","einigen","zehntelprozentpunkten","gegenüber","niedrigeren","finanzierung","markt","möglich","aber","garantiert","gesetzlich","festgelegt.","beispiel","440.000","plus","tilgung","ergeben","rund","2.383","monatsrate","380.000"]},{"kind":"article","id":"5-afa-wann-ist-sie-moglich","title":"5 % AfA – wann ist sie möglich?","category":"Steuern","summary":"„5 % AfA“ kann verschiedene Instrumente meinen. Besonders wichtig ist die Trennung zwischen degressiver AfA nach § 7 Abs. 5a EStG und der zusätzlichen Sonderabschreibung nach § 7b EStG.","answer":"5 % AfA ist nicht immer dieselbe Regel. Bei der degressiven AfA nach § 7 Abs. 5a EStG werden 5 % vom jeweiligen Restwert abgeschrieben – der Eurobetrag sinkt also jährlich. § 7b erlaubt bei erfüllten Voraussetzungen zusätzlich bis zu 5 % Sonderabschreibung im Jahr der Anschaffung/Herstellung und den drei folgenden Jahren auf eine begrenzte Bemessungsgrundlage. Entscheidungsrelevant: In Investmentmodellen AfA-Regime explizit benennen und Jahr für Jahr rechnen. Ein pauschaler konstanter 5-%-Ansatz überschätzt bei degressiver AfA die späteren Abschreibungsbeträge.","url":"/wissen/5-afa-wann-ist-sie-moglich/","keywords":["afa","wann","sie","möglich","kann","verschiedene","instrumente","meinen.","besonders","wichtig","trennung","zwischen","degressiver","nach","abs.","estg","zusätzlichen","sonderabschreibung","estg.","degressive","gebäude-afa","berechnet","vom","jeweiligen","restwert","sinkt","dadurch","jährlich.","dagegen","qualifizierten","mietwohnungsneubau","eigenen","voraussetzungen","bemessungsgrenzen.","immer","dieselbe","regel.","degressiven","abgeschrieben","eurobetrag","also","erlaubt","erfüllten","zusätzlich","bis","jahr","anschaffung/herstellung","drei","folgenden","jahren","begrenzte","bemessungsgrundlage.","entscheidungsrelevant","investmentmodellen","afa-regime","explizit","benennen","rechnen.","pauschaler","konstanter"]},{"kind":"article","id":"7b-estg-im-uberblick","title":"§ 7b EStG im Überblick","category":"Steuern","summary":"§ 7b EStG kann für begünstigten Mietwohnungsneubau eine zusätzliche Sonderabschreibung von bis zu 5 % pro Jahr ermöglichen – mit strengen Kosten-, Zeit- und Nachhaltigkeitsanforderungen.","answer":"Beispiel § 7b: 70 m² neue Mietwohnung mit 350.000 € begünstigten Anschaffungs-/Herstellungskosten = 5.000 €/m² und damit unter der gesetzlichen 5.200-€/m²-Grenze. Die Sonder-AfA-Basis ist trotzdem auf 4.000 €/m² begrenzt, also 280.000 €. 5 % davon sind 14.000 € Sonderabschreibung pro Jahr für den begünstigten Zeitraum, sofern alle weiteren Voraussetzungen erfüllt sind. Entscheidungsrelevant: § 7b nur in die Investmentrechnung aufnehmen, wenn Bauantrag/Bauanzeige, Kosten je m², Nutzungszweck und Nachhaltigkeitsvoraussetzungen dokumentiert sind.","url":"/wissen/7b-estg-im-uberblick/","keywords":["estg","überblick","kann","begünstigten","mietwohnungsneubau","zusätzliche","sonderabschreibung","bis","pro","jahr","ermöglichen","strengen","kosten-","zeit-","nachhaltigkeitsanforderungen.","aktuelle","fördergeneration","gelten","unter","anderem","bauantrags-/bauanzeigezeitraum","kostenobergrenze","quadratmeter","gedeckelte","bemessungsgrundlage.","neuere","förderphase","5.200","maximal","4.000","sonder-afa-basis","gesetzlich","verankert.","beispiel","neue","mietwohnung","350.000","anschaffungs-/herstellungskosten","5.000","damit","gesetzlichen","5.200-","grenze.","trotzdem","begrenzt","also","280.000","davon","14.000","zeitraum","sofern","alle","weiteren","voraussetzungen","erfüllt","sind.","entscheidungsrelevant","investmentrechnung","aufnehmen","wenn"]},{"kind":"article","id":"afa-richtig-berechnen","title":"AfA richtig berechnen","category":"Steuern","summary":"Die Gebäude-AfA beginnt mit der korrekten Bemessungsgrundlage: Kaufpreis plus zurechenbare Erwerbsnebenkosten werden auf Gebäude und nicht abschreibbaren Grund und Boden aufgeteilt.","answer":"Beispiel: 500.000 € Kaufpreis + 50.000 € zurechenbare Erwerbsnebenkosten, davon 75 % Gebäudeanteil = 412.500 € AfA-Bemessungsgrundlage. Bei 2 % linearer AfA wären das 8.250 € pro Jahr, bei 3 % 12.375 €. Der richtige Satz hängt u. a. vom Fertigstellungszeitpunkt und den gesetzlichen Voraussetzungen ab. Entscheidungsrelevant: Vor Renditerechnung Gebäudeanteil, Nebenkostenallokation und anwendbaren AfA-Satz getrennt bestimmen. Eine pauschale „2 % vom Kaufpreis“-Rechnung ist fachlich falsch.","url":"/wissen/afa-richtig-berechnen/","keywords":["afa","richtig","berechnen","gebäude-afa","beginnt","korrekten","bemessungsgrundlage","kaufpreis","plus","zurechenbare","erwerbsnebenkosten","gebäude","abschreibbaren","grund","boden","aufgeteilt.","steuerliche","verteilung","abschreibungsfähigen","gebäudeanschaffungs-","herstellungskosten","über","gesetzliche","bzw.","nachgewiesene","nutzungsdauer.","planmäßig","abgeschrieben.","beispiel","500.000","50.000","davon","gebäudeanteil","412.500","afa-bemessungsgrundlage.","linearer","wären","8.250","pro","jahr","12.375","richtige","satz","hängt","vom","fertigstellungszeitpunkt","gesetzlichen","voraussetzungen","ab.","entscheidungsrelevant","vor","renditerechnung","nebenkostenallokation","anwendbaren","afa-satz","getrennt","bestimmen.","pauschale","rechnung","fachlich"]},{"kind":"article","id":"annuitatendarlehen-erklart","title":"Annuitätendarlehen erklärt","category":"Finanzierung","summary":"Wie sich eine konstante Annuität in Zins, Tilgung und Restschuld zerlegt – und warum ein Tilgungsdarlehen trotz gleichem Start-Tilgungsbetrag anders verläuft.","answer":"Beim Annuitätendarlehen bleibt die Rate während der Zinsbindung grundsätzlich konstant, während sich ihre Zusammensetzung verschiebt. Bei 300.000 € Darlehen, 4,0 % Sollzins und 2,0 % Anfangstilgung beträgt die anfängliche Monatsrate 1.500 €. Im Zeitverlauf sinkt der Zinsanteil und die Tilgung beschleunigt sich. Im Vergleich zum Tilgungsdarlehen ist die Rate stabiler, die Restschuldentwicklung aber anders. Entscheidungsrelevant: Die tragfähige Finanzierung ist nicht die mit der niedrigsten Start-Rate, sondern diejenige, deren Restschuld und Anschlussrisiko zum geplanten Haltedauer-, Einkommens- und Liquiditätsszenario passen.","url":"/wissen/annuitatendarlehen-erklart/","keywords":["annuitätendarlehen","erklärt","konstante","annuität","zins","tilgung","restschuld","zerlegt","warum","tilgungsdarlehen","trotz","gleichem","start-tilgungsbetrag","anders","verläuft.","kombiniert","während","sollzinsbindung","grundsätzlich","konstanten","rate.","konstant","zahlung","ihre","zusammensetzung","sinkender","nimmt","zinsanteil","tilgungsanteil","zu.","beim","bleibt","rate","zinsbindung","verschiebt.","300.000","darlehen","sollzins","anfangstilgung","beträgt","anfängliche","monatsrate","1.500","zeitverlauf","sinkt","beschleunigt","sich.","vergleich","zum","stabiler","restschuldentwicklung","aber","anders.","entscheidungsrelevant","tragfähige","finanzierung","niedrigsten","start-rate","sondern","diejenige"]},{"kind":"article","id":"anschlussfinanzierung-planen","title":"Anschlussfinanzierung planen","category":"Finanzierung","summary":"Bei der Anschlussfinanzierung wird nicht der alte Kaufpreis neu finanziert, sondern die verbleibende Restschuld. Deshalb sollte die Planung Jahre vor dem Zinsbindungsende mit einer Restschuld- und Zinssensitivität beginnen.","answer":"Bei der Anschlussfinanzierung zählt die Restschuld zum Zinsbindungsende. Beispiel: 270.000 € Restschuld und 2 % neue Tilgung führen bei 3,0 % Sollzins zu ca. 1.125 € Monatsrate, bei 4,5 % zu 1.463 € und bei 6,0 % zu 1.800 €. Deshalb sollte nicht erst kurz vor Ablauf gerechnet werden. Entscheidungsrelevant: Mindestens drei Anschlusszins-Szenarien rechnen und prüfen, ob die Rate auch im oberen Szenario aus Einkommen bzw. Objektüberschuss tragbar ist.","url":"/wissen/anschlussfinanzierung-planen/","keywords":["anschlussfinanzierung","planen","alte","kaufpreis","neu","finanziert","sondern","verbleibende","restschuld.","deshalb","sollte","planung","jahre","vor","zinsbindungsende","restschuld-","zinssensitivität","beginnen.","ersetzt","restschuld","nach","ablauf","sollzinsbindung.","sie","kann","prolongation","bisherigen","bank","umschuldung","neuen","frühzeitiger","sicherung","forward-darlehen","strukturiert","werden.","zählt","zum","zinsbindungsende.","beispiel","270.000","neue","tilgung","führen","sollzins","ca.","1.125","monatsrate","1.463","1.800","erst","kurz","gerechnet","entscheidungsrelevant","mindestens","drei","anschlusszins-szenarien","rechnen","prüfen","rate","oberen"]},{"kind":"article","id":"beleihungsauslauf-und-kondition","title":"Beleihungsauslauf und Kondition","category":"Finanzierung","summary":"Der Beleihungsauslauf bezieht das Darlehen auf den bankseitigen Beleihungswert – nicht auf den Kaufpreis. Genau deshalb kann eine scheinbare 100-%-Finanzierung bankintern deutlich über 100 % liegen.","answer":"Der Beleihungsauslauf = Darlehen / Beleihungswert. Kauft jemand für 400.000 € und die Bank setzt nur 360.000 € Beleihungswert an, entsprechen 400.000 € Darlehen einem Beleihungsauslauf von rund 111 %, obwohl der Kaufpreis zu 100 % finanziert wird. Das kann Kondition und Darstellbarkeit deutlich beeinflussen. Entscheidungsrelevant: Eigenkapitalentscheidungen sollten an konkreten Bank-Konditionsstufen ausgerichtet werden. Der Beleihungsauslauf ist dafür oft die wichtigere Größe als die bloße Kaufpreisfinanzierungsquote.","url":"/wissen/beleihungsauslauf-und-kondition/","keywords":["beleihungsauslauf","kondition","bezieht","darlehen","bankseitigen","beleihungswert","kaufpreis.","genau","deshalb","kann","scheinbare","100-%-finanzierung","bankintern","deutlich","über","100","liegen.","verhältnis","relevanten","darlehenssumme","zum","bank","angesetzten","beleihungswert.","vorsichtiger","aktueller","marktpreis","unter","kaufpreis","kauft","jemand","400.000","setzt","360.000","entsprechen","rund","111","obwohl","finanziert","wird.","darstellbarkeit","beeinflussen.","entscheidungsrelevant","eigenkapitalentscheidungen","sollten","konkreten","bank-konditionsstufen","ausgerichtet","werden.","dafür","oft","wichtigere","größe","bloße","kaufpreisfinanzierungsquote."]},{"kind":"article","id":"bereitstellungszinsen","title":"Bereitstellungszinsen","category":"Finanzierung","summary":"Bereitstellungszinsen verteuern Darlehen, die zugesagt, aber nach einer freien Frist noch nicht abgerufen sind. Besonders relevant bei Bauträger- und Sanierungsfinanzierungen.","answer":"Bereitstellungszinsen entstehen auf noch nicht abgerufene Darlehensteile nach Ende der freien Bereitstellungszeit. Beispiel: 200.000 € noch nicht abgerufen und 0,25 % pro Monat ergeben 500 € Kosten pro Monat. Bei KfW 297/298 wird nach aktueller Produktinformation ab dem 13. Monat 0,15 % pro Monat auf den noch nicht abgerufenen Betrag berechnet. Entscheidungsrelevant: Bei Neubau und Sanierung nicht nur Sollzins vergleichen: bereitstellungsfreie Zeit, Zahlungsplan und mögliche Bauverzögerung monetarisieren.","url":"/wissen/bereitstellungszinsen/","keywords":["bereitstellungszinsen","verteuern","darlehen","zugesagt","aber","nach","freien","frist","noch","abgerufen","sind.","besonders","relevant","bauträger-","sanierungsfinanzierungen.","bzw.","provisionen","ausgezahlte","darlehensteile","erhoben","sobald","vertraglich","vereinbarte","bereitstellungszinsfreie","zeit","abgelaufen","ist.","höhe","freiphase","bankabhängig.","entstehen","abgerufene","ende","bereitstellungszeit.","beispiel","200.000","pro","monat","ergeben","500","kosten","monat.","kfw","297/298","aktueller","produktinformation","13.","abgerufenen","betrag","berechnet.","entscheidungsrelevant","neubau","sanierung","sollzins","vergleichen","bereitstellungsfreie","zahlungsplan","mögliche","bauverzögerung","monetarisieren."]},{"kind":"article","id":"bodenrichtwert-richtig-lesen","title":"Bodenrichtwert richtig lesen","category":"Marktanalysen","summary":"Der Bodenrichtwert ist ein durchschnittlicher Lagewert für ein definiertes Gebiet.","answer":"Der Bodenrichtwert ist ein durchschnittlicher Lagewert für ein definiertes Gebiet. Der Bodenrichtwert ist ein durchschnittlicher Lagewert für den Boden innerhalb einer Bodenrichtwertzone und kein verbindlicher Einzelgrundstückspreis. Entscheidungsrelevant: Der Wert eignet sich als Plausibilitätsanker, nicht als Ersatz für Vergleichskaufpreise oder eine objektspezifische Wertermittlung.","url":"/wissen/bodenrichtwert-richtig-lesen/","keywords":["bodenrichtwert","richtig","lesen","durchschnittlicher","lagewert","definiertes","gebiet.","kein","automatischer","grundstückswert.","grundstückszuschnitt","nutzung","erschließung","wertrelevante","merkmale","können","abweichen.","boden","innerhalb","bodenrichtwertzone","verbindlicher","einzelgrundstückspreis.","entscheidungsrelevant","wert","eignet","plausibilitätsanker","ersatz","vergleichskaufpreise","objektspezifische","wertermittlung.","gebiet"]},{"kind":"article","id":"brutto-vs-nettomietrendite","title":"Brutto- vs. Nettomietrendite","category":"Kapitalanlage","summary":"Die Bruttorendite teilt Jahresnettokaltmiete durch Kaufpreis. Die Nettorendite berücksichtigt laufende Eigentümerkosten.","answer":"Die Bruttorendite teilt Jahresnettokaltmiete durch Kaufpreis. Die Nettorendite berücksichtigt laufende Eigentümerkosten. Die Bruttomietrendite setzt Jahresnettokaltmiete ins Verhältnis zum Kaufpreis und ignoriert Erwerbsnebenkosten sowie laufende Eigentümerkosten. Entscheidungsrelevant: Bruttorendite eignet sich zum schnellen Screening; eine Kaufentscheidung sollte mindestens Nettorendite, Cashflow und CapEx berücksichtigen.","url":"/wissen/brutto-vs-nettomietrendite/","keywords":["brutto-","vs.","nettomietrendite","bruttorendite","teilt","jahresnettokaltmiete","durch","kaufpreis.","nettorendite","berücksichtigt","laufende","eigentümerkosten.","beide","kennzahlen","vor","finanzierung.","vergleich","sollten","berechnungsbasis","kostenabgrenzung","identisch","sein.","bruttomietrendite","setzt","ins","verhältnis","zum","kaufpreis","ignoriert","erwerbsnebenkosten","sowie","entscheidungsrelevant","eignet","schnellen","screening","kaufentscheidung","sollte","mindestens","cashflow","capex","berücksichtigen.","brutto","eigentümerkosten"]},{"kind":"article","id":"bruttogeschossflache-vs-wohnflache","title":"Bruttogeschossfläche vs. Wohnfläche","category":"Immobilienkauf","summary":"Flächenbegriffe sind nicht austauschbar.","answer":"Flächenbegriffe sind nicht austauschbar. Bruttogrund-/Geschossflächen und Wohnfläche beruhen auf unterschiedlichen Definitionen und dürfen nicht für €/m²-Vergleiche vermischt werden. Entscheidungsrelevant: Vor jedem €/m²-Vergleich muss klar sein, welche Flächendefinition im Zähler/Nenner verwendet wurde.","url":"/wissen/bruttogeschossflache-vs-wohnflache/","keywords":["bruttogeschossfläche","vs.","wohnfläche","flächenbegriffe","austauschbar.","miete","kaufpreis","pro","quadratmeter","sollten","richtigen","dokumentierten","fläche","basieren.","bruttogrund-/geschossflächen","beruhen","unterschiedlichen","definitionen","dürfen","vergleiche","vermischt","werden.","entscheidungsrelevant","vor","jedem","vergleich","muss","klar","sein","welche","flächendefinition","zähler/nenner","verwendet","wurde.","austauschbar"]},{"kind":"article","id":"capex-statt-schonrechnung","title":"Capex statt Schönrechnung","category":"Kapitalanlage","summary":"Größere Investitionen gehören getrennt von laufenden Kosten in die Planung.","answer":"Größere Investitionen gehören getrennt von laufenden Kosten in die Planung. CapEx sind größere, unregelmäßige Investitionen in die Substanz, etwa Dach, Fassade, Heizung, Leitungen oder Fenster. Sie verschwinden nicht dadurch, dass sie nicht jährlich anfallen. Entscheidungsrelevant: Der Kaufpreisvorteil eines sanierungsbedürftigen Objekts muss gegen den Barwert künftiger CapEx und mögliche Miet-/Leerstandsfolgen gerechnet werden.","url":"/wissen/capex-statt-schonrechnung/","keywords":["capex","statt","schönrechnung","größere","investitionen","gehören","getrennt","laufenden","kosten","planung.","dach","fassade","heizung","leitungen","energetische","maßnahmen","können","renditen","stark","verändern.","technischer","plan","über","zehn","bis","zwanzig","jahre","schafft","transparenz.","unregelmäßige","substanz","etwa","fenster.","sie","verschwinden","dadurch","jährlich","anfallen.","entscheidungsrelevant","kaufpreisvorteil","eines","sanierungsbedürftigen","objekts","muss","gegen","barwert","künftiger","mögliche","miet-/leerstandsfolgen","gerechnet","werden.","planung"]},{"kind":"article","id":"cashflow-verstehen","title":"Cashflow verstehen","category":"Kapitalanlage","summary":"Cashflow zeigt, welcher laufende Überschuss oder Zuschuss nach Miete, Kosten und Finanzierung verbleibt.","answer":"Cashflow zeigt, welcher laufende Überschuss oder Zuschuss nach Miete, Kosten und Finanzierung verbleibt. Cashflow misst Zahlungsströme, nicht steuerlichen Gewinn und nicht automatisch Vermögensaufbau. Tilgung ist Liquiditätsabfluss, erhöht aber gleichzeitig das Eigenkapital im Objekt. Entscheidungsrelevant: Cashflow immer zusammen mit Eigenkapitalbindung, Tilgung, Rücklagen und einem Stressszenario lesen.","url":"/wissen/cashflow-verstehen/","keywords":["cashflow","verstehen","zeigt","welcher","laufende","überschuss","zuschuss","nach","miete","kosten","finanzierung","verbleibt.","positiver","automatisch","gutes","investment","negativer","schlecht.","tilgung","baut","vermögen","während","rücklagen","mietausfall","steuern","liquidität","beeinflussen.","misst","zahlungsströme","steuerlichen","gewinn","vermögensaufbau.","liquiditätsabfluss","erhöht","aber","gleichzeitig","eigenkapital","objekt.","entscheidungsrelevant","immer","zusammen","eigenkapitalbindung","stressszenario","lesen.","verbleibt"]},{"kind":"article","id":"deal-screening-in-funf-minuten","title":"Deal-Screening in fünf Minuten","category":"Kapitalanlage","summary":"Ein schneller Check nutzt Kaufpreis, Jahresmiete, nicht umlagefähige Kosten, Zins und Tilgung.","answer":"Ein schneller Check nutzt Kaufpreis, Jahresmiete, nicht umlagefähige Kosten, Zins und Tilgung. Ein Schnell-Screening soll schlechte Deals früh aussortieren, nicht die Due Diligence ersetzen. Es arbeitet deshalb mit wenigen harten Größen: Gesamtinvestition, JNKM, nicht umlagefähige Kosten, CapEx, Finanzierung und realistische Marktmiete. Entscheidungsrelevant: Ziel des Screenings ist eine klare Entscheidung: verwerfen, Unterlagen nachfordern oder vertieft prüfen.","url":"/wissen/deal-screening-in-funf-minuten/","keywords":["deal-screening","fünf","minuten","schneller","check","nutzt","kaufpreis","jahresmiete","umlagefähige","kosten","zins","tilgung.","besteht","deal","schnelltest","folgt","vollständige","prüfung","dokumenten","szenarien.","schnell-screening","soll","schlechte","deals","früh","aussortieren","due","diligence","ersetzen.","arbeitet","deshalb","wenigen","harten","größen","gesamtinvestition","jnkm","capex","finanzierung","realistische","marktmiete.","entscheidungsrelevant","ziel","screenings","klare","entscheidung","verwerfen","unterlagen","nachfordern","vertieft","prüfen.","screening","tilgung"]},{"kind":"article","id":"dscr-verstehen","title":"DSCR verstehen","category":"Finanzierung","summary":"Der Debt Service Coverage Ratio zeigt, wie oft der operative Nettoertrag den Kapitaldienst deckt. Er ist besonders bei Mehrfamilienhäusern und gewerblichen Finanzierungen relevant.","answer":"DSCR misst die Kapitaldienstdeckung. Bei 48.000 € nachhaltigem Nettoertrag und 36.000 € Jahreskapitaldienst beträgt der DSCR 1,33. Sinkt der Ertrag um 10 % auf 43.200 €, fällt der DSCR auf 1,20. Steigt gleichzeitig der Kapitaldienst auf 42.000 €, liegt er nur noch bei 1,03. Entscheidungsrelevant: Ein Investment mit DSCR knapp über 1,00 hat kaum Puffer. Bei MFH sollte der DSCR zusätzlich mit Mietrückgang, Zinsanstieg und CapEx-Belastung gestresst werden.","url":"/wissen/dscr-verstehen/","keywords":["dscr","verstehen","debt","service","coverage","ratio","zeigt","oft","operative","nettoertrag","kapitaldienst","deckt.","besonders","mehrfamilienhäusern","gewerblichen","finanzierungen","relevant.","net","operating","income","bzw.","definierter","nachhaltiger","kapitaldienstdeckungsbetrag","jährlicher","kapitaldienst.","bedeutet","exakt","deckend","oberhalb","bleibt","puffer","unterhalb","reicht","definierte","ertrag","aus.","misst","kapitaldienstdeckung.","48.000","nachhaltigem","36.000","jahreskapitaldienst","beträgt","33.","sinkt","43.200","fällt","20.","steigt","gleichzeitig","42.000","liegt","noch","03.","entscheidungsrelevant","investment","knapp","über","hat"]},{"kind":"article","id":"due-diligence-fur-einsteiger","title":"Due Diligence für Einsteiger","category":"Immobilienkauf","summary":"Eine strukturierte Prüfung umfasst Recht, Technik, Miete, Markt, Finanzierung und Steuern.","answer":"Eine strukturierte Prüfung umfasst Recht, Technik, Miete, Markt, Finanzierung und Steuern. Due Diligence verbindet rechtliche, technische, wirtschaftliche und finanzielle Prüfung. Eine gute Renditekennzahl kann einen ungeklärten Grundbuchvermerk oder Sanierungsstau nicht kompensieren. Entscheidungsrelevant: Am Ende steht keine Checkliste, sondern eine Entscheidungsmatrix: bestätigt, preisrelevant, vertraglich abzusichern oder Dealbreaker.","url":"/wissen/due-diligence-fur-einsteiger/","keywords":["due","diligence","einsteiger","strukturierte","prüfung","umfasst","recht","technik","miete","markt","finanzierung","steuern.","rechner","wirtschaftliche","ebene.","dokumente","annahmen","müssen","verifiziert","werden.","verbindet","rechtliche","technische","finanzielle","prüfung.","gute","renditekennzahl","kann","ungeklärten","grundbuchvermerk","sanierungsstau","kompensieren.","entscheidungsrelevant","ende","steht","keine","checkliste","sondern","entscheidungsmatrix","bestätigt","preisrelevant","vertraglich","abzusichern","dealbreaker.","steuern"]},{"kind":"article","id":"eigenkapital-optimal-einsetzen","title":"Eigenkapital optimal einsetzen","category":"Finanzierung","summary":"Mehr Eigenkapital reduziert Darlehen und kann den Beleihungsauslauf verbessern. Optimal ist aber nicht automatisch maximal: Liquiditätsreserve und Opportunitätskosten gehören in dieselbe Rechnung.","answer":"Mehr Eigenkapital führt häufig zu niedrigeren Darlehensbeträgen und kann günstigere Bankkonditionen ermöglichen. Der Zusammenhang ist jedoch stufenweise statt linear. Beispiel: Bei 400.000 € Kaufpreis + 40.000 € Nebenkosten führen 40.000 €, 80.000 € oder 120.000 € Eigenkapital zu sehr unterschiedlichen Darlehen, Raten und Liquiditätsreserven. Optimal ist die Struktur, bei der Kondition und Rate tragfähig sind, ohne die Reserve auf null zu setzen. Entscheidungsrelevant: Eigenkapital so einsetzen, dass eine wirtschaftlich attraktive Bankstufe erreicht wird und danach noch ein belastbarer Liquiditätspuffer verbleibt. Nicht „maximal viel EK“, sondern „marginal sinnvoll eingesetztes EK“ ist die richtige Fragestellung.","url":"/wissen/eigenkapital-optimal-einsetzen/","keywords":["eigenkapital","optimal","einsetzen","mehr","reduziert","darlehen","kann","beleihungsauslauf","verbessern.","aber","automatisch","maximal","liquiditätsreserve","opportunitätskosten","gehören","dieselbe","rechnung.","wirkt","immobilienfinanzierung","drei","ebenen","kreditbetrag","günstigere","beleihungsstufen","ermöglichen","senkt","absolute","zinsbelastung.","gleichzeitig","bindet","liquidität","nach","kauf","rücklagen","andere","anlagen","fehlen","kann.","führt","häufig","niedrigeren","darlehensbeträgen","bankkonditionen","ermöglichen.","zusammenhang","jedoch","stufenweise","statt","linear.","beispiel","400.000","kaufpreis","40.000","nebenkosten","führen","80.000","120.000","sehr","unterschiedlichen","raten"]},{"kind":"article","id":"energiezustand-und-finanzierung","title":"Energiezustand und Finanzierung","category":"Finanzierung","summary":"Der energetische Zustand beeinflusst nicht nur Betriebskosten, sondern zunehmend auch Objektbewertung, Sanierungsbedarf, Förderfähigkeit und damit die Finanzierungsstruktur.","answer":"Ein schlechter Energiezustand kann die Finanzierung indirekt verteuern: zusätzlicher Sanierungsbedarf erhöht den Mittelbedarf und kann den bankseitigen Objektwert beeinflussen. Deshalb sollte ein Kaufpreis nie ohne Modernisierungsbudget finanziert werden. Bei förderfähigen Maßnahmen können KfW-/BEG-Bausteine die Struktur verändern. Entscheidungsrelevant: Sanierungsbedarf als Teil der Gesamtinvestition finanzieren und nicht nach Kauf aus einer bereits aufgebrauchten Liquiditätsreserve improvisieren.","url":"/wissen/energiezustand-und-finanzierung/","keywords":["energiezustand","finanzierung","energetische","zustand","beeinflusst","betriebskosten","sondern","zunehmend","objektbewertung","sanierungsbedarf","förderfähigkeit","damit","finanzierungsstruktur.","relevant","weil","notwendige","modernisierungen","zusätzlichen","kapitalbedarf","erzeugen","banken","objektqualität","bzw.","zukunftsfähigkeit","ihre","bewertung","einbeziehen","können.","energieausweis","heizungsart","sanierungsfahrplan","sollten","deshalb","vor","kreditstruktur","geprüft","werden.","schlechter","kann","indirekt","verteuern","zusätzlicher","erhöht","mittelbedarf","bankseitigen","objektwert","beeinflussen.","sollte","kaufpreis","nie","ohne","modernisierungsbudget","finanziert","förderfähigen","maßnahmen","können","kfw-/beg-bausteine","struktur","verändern.","entscheidungsrelevant"]},{"kind":"article","id":"ertragswertverfahren-kompakt","title":"Ertragswertverfahren kompakt","category":"Immobilienkauf","summary":"Das Ertragswertverfahren leitet den Wert aus nachhaltig erzielbaren Erträgen ab.","answer":"Das Ertragswertverfahren leitet den Wert aus nachhaltig erzielbaren Erträgen ab. Das Ertragswertverfahren leitet den Wert wesentlich aus nachhaltig erzielbaren Erträgen ab. Es trennt Bodenwert und Ertragswert der baulichen Anlagen. Entscheidungsrelevant: Das Verfahren ist besonders relevant bei Renditeobjekten; für die Kaufentscheidung sollte die Bewertung mit tatsächlichem Cashflow und CapEx gespiegelt werden.","url":"/wissen/ertragswertverfahren-kompakt/","keywords":["ertragswertverfahren","kompakt","leitet","wert","aus","nachhaltig","erzielbaren","erträgen","ab.","bewirtschaftungskosten","bodenwert","liegenschaftszins","restnutzungsdauer","zentrale","komponenten.","wesentlich","trennt","ertragswert","baulichen","anlagen.","entscheidungsrelevant","verfahren","besonders","relevant","renditeobjekten","kaufentscheidung","sollte","bewertung","tatsächlichem","cashflow","capex","gespiegelt","werden."]},{"kind":"article","id":"exit-kosten-berucksichtigen","title":"Exit-Kosten berücksichtigen","category":"Kapitalanlage","summary":"Beim Verkauf entstehen häufig Makler-, Rechts-, Vorfälligkeits- und Abwicklungskosten.","answer":"Beim Verkauf entstehen häufig Makler-, Rechts-, Vorfälligkeits- und Abwicklungskosten. Beim Exit fallen je nach Objekt Makler-, Notar-/Löschungs-, Vorfälligkeits- und gegebenenfalls Steuerkosten an. Ein Verkaufspreis ist daher nicht gleich Nettoerlös. Entscheidungsrelevant: Exitrechnung immer als Nettoverkaufserlös nach Kosten minus Restschuld darstellen.","url":"/wissen/exit-kosten-berucksichtigen/","keywords":["exit-kosten","berücksichtigen","beim","verkauf","entstehen","häufig","makler-","rechts-","vorfälligkeits-","abwicklungskosten.","erwartete","verkaufspreis","sollte","daher","vollständig","rückfluss","angesetzt","werden.","exit","fallen","nach","objekt","notar-/löschungs-","gegebenenfalls","steuerkosten","an.","gleich","nettoerlös.","entscheidungsrelevant","exitrechnung","immer","nettoverkaufserlös","kosten","minus","restschuld","darstellen.","abwicklungskosten","makler","rechts","vorfälligkeits"]},{"kind":"article","id":"finanzierungsreserve-planen","title":"Finanzierungsreserve planen","category":"Finanzierung","summary":"Eine Finanzierung sollte nicht das letzte verfügbare liquide Euro binden. Reserve schützt vor Kostenüberschreitungen, Sonderumlagen, Leerstand und ungeplanten Reparaturen.","answer":"Eine Finanzierung ohne Liquiditätsreserve kann trotz guter Bankkondition fragil sein. Beispiel: 80.000 € verfügbares Eigenkapital bei 40.000 € Nebenkosten. Wer die übrigen 40.000 € vollständig in den Kaufpreis steckt, reduziert zwar das Darlehen, hat aber keinen Puffer. Oft ist ein etwas höheres Darlehen mit 15–25 T€ Reserve wirtschaftlich robuster. Entscheidungsrelevant: Reservegröße anhand der wahrscheinlichsten Schaden-/CapEx-Ereignisse bestimmen und erst danach entscheiden, wie viel Rest-Eigenkapital die Bankkondition verbessert.","url":"/wissen/finanzierungsreserve-planen/","keywords":["finanzierungsreserve","planen","finanzierung","sollte","letzte","verfügbare","liquide","euro","binden.","reserve","schützt","vor","kostenüberschreitungen","sonderumlagen","leerstand","ungeplanten","reparaturen.","nach","kauf","nebenkosten","verbleibende","kurzfristig","liquidität.","sie","keine","renditekennzahl","sondern","risikopuffer","gegen","ereignisse","sinnvoll","über","langfristigen","immobilienkredit","nachfinanziert","können.","ohne","liquiditätsreserve","kann","trotz","guter","bankkondition","fragil","sein.","beispiel","80.000","verfügbares","eigenkapital","40.000","nebenkosten.","wer","übrigen","vollständig","kaufpreis","steckt","reduziert","zwar","darlehen","hat","aber"]},{"kind":"article","id":"forward-darlehen","title":"Forward-Darlehen","category":"Finanzierung","summary":"Ein Forward-Darlehen sichert heute den Sollzins einer künftigen Anschlussfinanzierung. Entscheidend sind Vorlaufzeit, Forward-Aufschlag, erwartete Restschuld und das Risiko fallender Zinsen.","answer":"Ein Forward-Darlehen fixiert heute den Zinssatz für eine Anschlussfinanzierung, die erst später startet. Beispiel: 250.000 € erwartete Restschuld im Jahr 2031, heute gesicherter Forward-Sollzins 4,3 % und 2 % Tilgung ergeben rund 1.313 € Monatsrate. Liegt der Markt 2031 bei 5,5 %, läge eine gleich strukturierte neue Finanzierung bei rund 1.563 €; fällt der Markt auf 3,0 %, wäre sie nur rund 1.042 € teuer. Der Schutz gegen steigende Zinsen wird also mit dem Risiko erkauft, bei fallenden Zinsen an den höheren Forward-Zins gebunden zu sein. Entscheidungsrelevant: Forward nicht nach Bauchgefühl abschließen: erwartete Restschuld, Forward-Aufschlag, Stressrate ohne Absicherung und finanzielle Tragfähigkeit in mindestens drei Zinsszenarien vergleichen.","url":"/wissen/forward-darlehen/","keywords":["forward-darlehen","sichert","heute","sollzins","künftigen","anschlussfinanzierung.","entscheidend","vorlaufzeit","forward-aufschlag","erwartete","restschuld","risiko","fallender","zinsen.","verbindlich","abgeschlossen","aber","erst","späteren","termin","zur","ablösung","bestehenden","finanzierung","ausgezahlt.","damit","zinsabsicherung","künftige","keine","unverbindliche","option.","fixiert","zinssatz","anschlussfinanzierung","später","startet.","beispiel","250.000","jahr","2031","gesicherter","forward-sollzins","tilgung","ergeben","rund","1.313","monatsrate.","liegt","markt","läge","gleich","strukturierte","neue","1.563","fällt","wäre","sie","1.042","teuer.","schutz"]},{"kind":"article","id":"gebaudeanteil-berechnen","title":"Gebäudeanteil berechnen","category":"Steuern","summary":"Für die AfA muss ein Gesamtkaufpreis auf Grund und Boden sowie Gebäude aufgeteilt werden. Maßgeblich ist eine wirtschaftlich haltbare Wertrelation – nicht eine frei gewählte Restwertmethode.","answer":"Beispiel Kaufpreisaufteilung: Bodenwert 250.000 €, Gebäudewert 450.000 € → Gebäudeanteil 64,29 %. Bei 600.000 € Gesamtkaufpreis entfallen damit rund 385.714 € auf das Gebäude und rund 214.286 € auf Grund und Boden. Die Quote muss sachgerecht hergeleitet werden. Entscheidungsrelevant: Gebäudequote vor dem Kauf steuerlich plausibilisieren; sie beeinflusst die AfA über viele Jahre und kann Renditevergleiche erheblich verändern.","url":"/wissen/gebaudeanteil-berechnen/","keywords":["gebäudeanteil","berechnen","afa","muss","gesamtkaufpreis","grund","boden","sowie","gebäude","aufgeteilt","werden.","maßgeblich","wirtschaftlich","haltbare","wertrelation","frei","gewählte","restwertmethode.","anteil","gesamtkaufpreises","abschreibbare","entfällt.","nach","bmf/bfh-systematik","verhältnis","geeigneter","verkehrswerte","bzw.","teilwerte","tatsächlichen","kaufpreis","übertragen.","beispiel","kaufpreisaufteilung","bodenwert","250.000","gebäudewert","450.000","600.000","entfallen","damit","rund","385.714","214.286","boden.","quote","sachgerecht","hergeleitet","entscheidungsrelevant","gebäudequote","vor","kauf","steuerlich","plausibilisieren","sie","beeinflusst","über","viele","jahre","kann"]},{"kind":"article","id":"immobilien-gmbh-oder-privatvermogen","title":"Immobilien-GmbH oder Privatvermögen?","category":"Steuern","summary":"Privatvermögen und Immobilien-GmbH unterscheiden sich bei laufender Besteuerung, Finanzierung, Ausschüttung, Veräußerung und Administrationsaufwand. Ein pauschales „GmbH spart Steuern“ ist fachlich unzureichend.","answer":"Eine Immobilien-GmbH ist nicht automatisch steuerlich besser als Privatvermögen. In der GmbH können laufende Gewinne bei passender Struktur anders belastet werden, aber Ausschüttungen und Veräußerungen folgen anderen Regeln. Im Privatvermögen kann bei Grundstücken nach mehr als zehn Jahren unter § 23 EStG ein steuerlich anderer Exit möglich sein. Rechtsformwahl gehört zum Steuerberater. Entscheidungsrelevant: Vor Gründung bzw. Ankauf eine Mehrjahresrechnung mit Steuerberater erstellen. Die Rechtsform ist Teil der Investmentstrategie und lässt sich nachträglich nicht ohne Transaktionsfolgen beliebig wechseln.","url":"/wissen/immobilien-gmbh-oder-privatvermogen/","keywords":["immobilien-gmbh","privatvermögen","unterscheiden","laufender","besteuerung","finanzierung","ausschüttung","veräußerung","administrationsaufwand.","pauschales","gmbh","spart","steuern","fachlich","unzureichend.","rechtsform","beeinflusst","steuersätze","sondern","finanzierungskonditionen","haftungsstruktur","liquiditätsentnahme","exitbesteuerung.","sinnvolle","entscheidung","hängt","deshalb","haltedauer","reinvestitionsstrategie","persönlichem","steuersatz","transaktionsplan","ab.","automatisch","steuerlich","besser","privatvermögen.","können","laufende","gewinne","passender","struktur","anders","belastet","aber","ausschüttungen","veräußerungen","folgen","anderen","regeln.","kann","grundstücken","nach","mehr","zehn","jahren","unter","estg","anderer","exit"]},{"kind":"article","id":"immobilien-vergleichen","title":"Immobilien vergleichen","category":"Immobilienkauf","summary":"Zwei Objekte sollten mit denselben Annahmen und demselben Zeitraum verglichen werden.","answer":"Zwei Objekte sollten mit denselben Annahmen und demselben Zeitraum verglichen werden. Ein sinnvoller Vergleich normalisiert Kaufpreis, Nebenkosten, Miete, CapEx, Finanzierung und Haltedauer auf dieselbe Basis. Entscheidungsrelevant: Nicht nach der höchsten Einzelkennzahl entscheiden, sondern nach einem konsistenten Score aus Ertrag, Risiko, Kapitalbindung und Exit-Liquidität.","url":"/wissen/immobilien-vergleichen/","keywords":["immobilien","vergleichen","zwei","objekte","sollten","denselben","annahmen","demselben","zeitraum","verglichen","werden.","neben","rendite","cashflow","zählen","kapitalbindung","restschuld","technisches","risiko","mikrolage","exit-liquidität.","sinnvoller","vergleich","normalisiert","kaufpreis","nebenkosten","miete","capex","finanzierung","haltedauer","dieselbe","basis.","entscheidungsrelevant","nach","höchsten","einzelkennzahl","entscheiden","sondern","konsistenten","score","aus","ertrag"]},{"kind":"article","id":"indexmiete-kalkulieren","title":"Indexmiete kalkulieren","category":"Vermietung","summary":"Indexmieten koppeln Anpassungen an den Verbraucherpreisindex.","answer":"Indexmieten koppeln Anpassungen an den Verbraucherpreisindex. Bei einer Indexmiete ist die Mietentwicklung an den Verbraucherpreisindex gekoppelt. Die Miete ändert sich nicht automatisch; die Anpassung muss nach den gesetzlichen Anforderungen geltend gemacht werden. Entscheidungsrelevant: Indexmiete ist kein garantierter Inflationsschutz: Vertragswirksamkeit, Ausgangsmiete, Indexentwicklung und tatsächliche Durchsetzung sind zu berücksichtigen.","url":"/wissen/indexmiete-kalkulieren/","keywords":["indexmiete","kalkulieren","indexmieten","koppeln","anpassungen","verbraucherpreisindex.","erfolgen","automatisch","formelle","vorgaben","gebunden.","inflation","zahlungsfähigkeit","mieter","getrennt","betrachten.","mietentwicklung","verbraucherpreisindex","gekoppelt.","miete","ändert","anpassung","muss","nach","gesetzlichen","anforderungen","geltend","gemacht","werden.","entscheidungsrelevant","kein","garantierter","inflationsschutz","vertragswirksamkeit","ausgangsmiete","indexentwicklung","tatsächliche","durchsetzung","berücksichtigen."]},{"kind":"article","id":"instandhaltungsrucklage-pro-quadratmeter","title":"Instandhaltungsrücklage pro Quadratmeter","category":"Kapitalanlage","summary":"Ein pauschaler Ansatz kann für die erste Kalkulation helfen.","answer":"Ein pauschaler Ansatz kann für die erste Kalkulation helfen. Pauschale Rücklagen pro Quadratmeter sind nur grobe Planungswerte. Der tatsächliche Bedarf hängt von Alter, Bauart, technischen Gewerken und bereits vorhandenem Rücklagenstand ab. Entscheidungsrelevant: Rücklagenwert immer gegen Dach, Fassade, Heizung, Leitungen, Fenster und Aufzüge plausibilisieren.","url":"/wissen/instandhaltungsrucklage-pro-quadratmeter/","keywords":["instandhaltungsrücklage","pro","quadratmeter","pauschaler","ansatz","kann","erste","kalkulation","helfen.","gebäudealter","zustand","konstruktion","bereits","vorhandene","rücklagen","wichtiger","fixer","wert.","fünf","bis","fünfzehn","euro","jahr","grobe","spannbreite.","pauschale","planungswerte.","tatsächliche","bedarf","hängt","alter","bauart","technischen","gewerken","vorhandenem","rücklagenstand","ab.","entscheidungsrelevant","rücklagenwert","immer","gegen","dach","fassade","heizung","leitungen","fenster","aufzüge","plausibilisieren.","helfen"]},{"kind":"article","id":"irr-bei-immobilien","title":"IRR bei Immobilien","category":"Kapitalanlage","summary":"Der interne Zinsfuß berücksichtigt Zeitpunkt und Höhe aller Zahlungsströme.","answer":"Der interne Zinsfuß berücksichtigt Zeitpunkt und Höhe aller Zahlungsströme. Die IRR ist der Diskontsatz, bei dem der Kapitalwert einer Zahlungsreihe null wird. Sie berücksichtigt Zeitpunkt und Höhe sämtlicher Ein- und Auszahlungen. Entscheidungsrelevant: IRR nur zusammen mit absolutem Kapitalwert, Eigenkapitaleinsatz und offengelegtem Exit-Szenario verwenden.","url":"/wissen/irr-bei-immobilien/","keywords":["irr","immobilien","interne","zinsfuß","berücksichtigt","zeitpunkt","höhe","aller","zahlungsströme.","sinnvoll","haltedauer-","exit-vergleiche","reagiert","aber","stark","angenommenen","verkaufspreis.","diskontsatz","kapitalwert","zahlungsreihe","null","wird.","sie","sämtlicher","ein-","auszahlungen.","entscheidungsrelevant","zusammen","absolutem","eigenkapitaleinsatz","offengelegtem","exit-szenario","verwenden.","zahlungsströme"]},{"kind":"article","id":"kapitalwert-verstehen","title":"Kapitalwert verstehen","category":"Kapitalanlage","summary":"Der Kapitalwert diskontiert künftige Zahlungsströme auf heute.","answer":"Der Kapitalwert diskontiert künftige Zahlungsströme auf heute. Der Kapitalwert diskontiert zukünftige Nettozahlungen auf den heutigen Zeitpunkt und zieht die Anfangsinvestition ab. Entscheidungsrelevant: Diskontsatz als Renditeanforderung explizit begründen und mindestens ein höheres Risikoszenario rechnen.","url":"/wissen/kapitalwert-verstehen/","keywords":["kapitalwert","verstehen","diskontiert","künftige","zahlungsströme","heute.","gewählte","diskontsatz","zentrale","annahme","sollte","risiko","sowie","alternative","anlagechancen","abbilden.","zukünftige","nettozahlungen","heutigen","zeitpunkt","zieht","anfangsinvestition","ab.","entscheidungsrelevant","renditeanforderung","explizit","begründen","mindestens","höheres","risikoszenario","rechnen.","heute"]},{"kind":"article","id":"kaufnebenkosten-vollstandig-erfassen","title":"Kaufnebenkosten vollständig erfassen","category":"Immobilienkauf","summary":"Grunderwerbsteuer, Notar, Grundbuch und gegebenenfalls Makler erhöhen den Kapitalbedarf.","answer":"Grunderwerbsteuer, Notar, Grundbuch und gegebenenfalls Makler erhöhen den Kapitalbedarf. Zu den Erwerbsnebenkosten gehören insbesondere Grunderwerbsteuer, Notar und Grundbuch sowie gegebenenfalls Maklercourtage. Höhe und Struktur hängen vom Bundesland und konkreten Geschäft ab. Entscheidungsrelevant: Kaufpreis, gesetzliche Erwerbsnebenkosten und nachgelagerte Investitionen getrennt ausweisen; so bleibt sichtbar, welche Kosten fremdfinanziert sind.","url":"/wissen/kaufnebenkosten-vollstandig-erfassen/","keywords":["kaufnebenkosten","vollständig","erfassen","grunderwerbsteuer","notar","grundbuch","gegebenenfalls","makler","erhöhen","kapitalbedarf.","zusätzlich","können","gutachten","finanzierungskosten","renovierung","bereitstellungszinsen","anfallen.","jede","position","jedem","fall","vorhanden.","erwerbsnebenkosten","gehören","insbesondere","sowie","maklercourtage.","höhe","struktur","hängen","vom","bundesland","konkreten","geschäft","ab.","entscheidungsrelevant","kaufpreis","gesetzliche","nachgelagerte","investitionen","getrennt","ausweisen","bleibt","sichtbar","welche","kosten","fremdfinanziert","sind.","kapitalbedarf"]},{"kind":"article","id":"kaufpreisfaktor-richtig-einordnen","title":"Kaufpreisfaktor richtig einordnen","category":"Kapitalanlage","summary":"Der Faktor ist Kaufpreis geteilt durch Jahresnettokaltmiete.","answer":"Der Faktor ist Kaufpreis geteilt durch Jahresnettokaltmiete. Der Kaufpreisfaktor ist Kaufpreis geteilt durch Jahresnettokaltmiete und damit der Kehrwert der Bruttomietrendite, sofern dieselben Bezugsgrößen verwendet werden. Entscheidungsrelevant: Faktor als Screeninggröße nutzen, danach Miete, CapEx, Mikrolage und Finanzierung separat prüfen.","url":"/wissen/kaufpreisfaktor-richtig-einordnen/","keywords":["kaufpreisfaktor","richtig","einordnen","faktor","kaufpreis","geteilt","durch","jahresnettokaltmiete.","kehrwert","bruttomietrendite","ignoriert","kosten","finanzierung","steuern","investitionsbedarf.","eignet","schneller","filter.","jahresnettokaltmiete","damit","sofern","dieselben","bezugsgrößen","verwendet","werden.","entscheidungsrelevant","screeninggröße","nutzen","danach","miete","capex","mikrolage","separat","prüfen."]},{"kind":"article","id":"leerstand-richtig-bewerten","title":"Leerstand richtig bewerten","category":"Vermietung","summary":"Leerstand kann marktbedingt, technisch oder strategisch sein.","answer":"Leerstand kann marktbedingt, technisch oder strategisch sein. Leerstand kann temporär, strukturell oder strategisch sein. Die wirtschaftliche Bewertung hängt davon ab, ob die Einheit kurzfristig vermietbar ist oder ein technisches/rechtliches Problem vorliegt. Entscheidungsrelevant: Leerstand nicht pauschal als Prozentsatz abziehen, sondern Ursache und erwartete Dauer je Einheit modellieren.","url":"/wissen/leerstand-richtig-bewerten/","keywords":["leerstand","richtig","bewerten","kann","marktbedingt","technisch","strategisch","sein.","bestandsobjekten","dauer","ursache","renovierungsbedarf","realistische","neuvermietungsmiete","prüfen.","temporär","strukturell","wirtschaftliche","bewertung","hängt","davon","einheit","kurzfristig","vermietbar","technisches/rechtliches","problem","vorliegt.","entscheidungsrelevant","pauschal","prozentsatz","abziehen","sondern","erwartete","modellieren.","sein"]},{"kind":"article","id":"ltv-verstehen","title":"LTV verstehen","category":"Finanzierung","summary":"Loan-to-Value (LTV) misst Fremdkapital im Verhältnis zum aktuellen oder definierten Objektwert. Der LTV kann sich sowohl durch Tilgung als auch durch Wertänderungen bewegen.","answer":"Ein LTV von 70 % bedeutet bei 500.000 € Objektwert und 350.000 € Restschuld, dass 70 % des Werts fremdfinanziert sind. Fällt der Wert auf 425.000 €, steigt der LTV ohne neue Kreditaufnahme auf rund 82,4 %. Tilgung wirkt umgekehrt und senkt den LTV. Entscheidungsrelevant: Für Portfolio- und Exit-Risiken ist der LTV als dynamische Größe nützlich: Wertverlust und Tilgung gleichzeitig stressen, statt den LTV nur am Ankaufstag zu betrachten.","url":"/wissen/ltv-verstehen/","keywords":["ltv","verstehen","loan-to-value","misst","fremdkapital","verhältnis","zum","aktuellen","definierten","objektwert.","kann","sowohl","durch","tilgung","wertänderungen","bewegen.","darlehenssaldo","anders","deutsche","bankinterne","beleihungsauslauf","investmentkontext","häufig","markt-","bewertungswert","verwendet.","deshalb","müssen","definition","bewertungsstichtag","immer","genannt","werden.","bedeutet","500.000","objektwert","350.000","restschuld","werts","fremdfinanziert","sind.","fällt","wert","425.000","steigt","ohne","neue","kreditaufnahme","rund","wirkt","umgekehrt","senkt","ltv.","entscheidungsrelevant","portfolio-","exit-risiken","dynamische","größe","nützlich","wertverlust"]},{"kind":"article","id":"mietausfall-kalkulieren","title":"Mietausfall kalkulieren","category":"Kapitalanlage","summary":"Mietausfall umfasst Leerstand, Zahlungsstörungen und nicht nahtlose Neuvermietung.","answer":"Mietausfall umfasst Leerstand, Zahlungsstörungen und nicht nahtlose Neuvermietung. Mietausfall umfasst nicht nur dauerhaft unbezahlte Miete, sondern auch Leerstand zwischen Mietverhältnissen, Verzögerungen und uneinbringliche Forderungen. Entscheidungsrelevant: Mindestens Basisszenario und Stressszenario mit zusätzlichem Leerstandsmonat beziehungsweise prozentualem Mietausfall rechnen.","url":"/wissen/mietausfall-kalkulieren/","keywords":["mietausfall","kalkulieren","umfasst","leerstand","zahlungsstörungen","nahtlose","neuvermietung.","pauschaler","ansatz","bis","drei","prozent","kann","erste","orientierung","sein","gewerbe","möblierten","konzepten","schwacher","nachfrage","muss","objektspezifisch","höher","angesetzt","werden.","dauerhaft","unbezahlte","miete","sondern","zwischen","mietverhältnissen","verzögerungen","uneinbringliche","forderungen.","entscheidungsrelevant","mindestens","basisszenario","stressszenario","zusätzlichem","leerstandsmonat","beziehungsweise","prozentualem","rechnen.","neuvermietung"]},{"kind":"article","id":"mietmultiplikator-und-faktor","title":"Mietmultiplikator und Faktor","category":"Kapitalanlage","summary":"Der Faktor beschreibt, wie viele Jahresnettokaltmieten dem Kaufpreis entsprechen.","answer":"Der Faktor beschreibt, wie viele Jahresnettokaltmieten dem Kaufpreis entsprechen. Mietmultiplikator, Vervielfältiger und Kaufpreisfaktor werden im Markt häufig synonym verwendet: Kaufpreis geteilt durch Jahresnettokaltmiete. Entscheidungsrelevant: Ist- und Soll-Miete getrennt ausweisen; ein Soll-Faktor ohne rechtlich und praktisch erreichbare Mietsteigerung ist keine belastbare Kennzahl.","url":"/wissen/mietmultiplikator-und-faktor/","keywords":["mietmultiplikator","faktor","beschreibt","viele","jahresnettokaltmieten","kaufpreis","entsprechen.","niedriger","automatisch","besser","lage","zustand","entwicklung","risiko","enthalten","sind.","vervielfältiger","kaufpreisfaktor","markt","häufig","synonym","verwendet","geteilt","durch","jahresnettokaltmiete.","entscheidungsrelevant","ist-","soll-miete","getrennt","ausweisen","soll-faktor","ohne","rechtlich","praktisch","erreichbare","mietsteigerung","keine","belastbare","kennzahl.","entsprechen"]},{"kind":"article","id":"mietspiegel-richtig-nutzen","title":"Mietspiegel richtig nutzen","category":"Vermietung","summary":"Der Mietspiegel unterstützt die Einordnung ortsüblicher Vergleichsmieten.","answer":"Der Mietspiegel unterstützt die Einordnung ortsüblicher Vergleichsmieten. Mietspiegel bilden die ortsübliche Vergleichsmiete nach gesetzlichen Kriterien ab und sind kein allgemeiner Marktpreisrechner für jede Wohnung. Entscheidungsrelevant: Für Mietsteigerungs- und Neuvermietungsmodelle die rechtliche Mietgrenze getrennt von beobachteten Angebotsmieten modellieren.","url":"/wissen/mietspiegel-richtig-nutzen/","keywords":["mietspiegel","richtig","nutzen","unterstützt","einordnung","ortsüblicher","vergleichsmieten.","wohnwertmerkmale","spanne","rechtlicher","anwendungsbereich","müssen","beachtet","werden.","bilden","ortsübliche","vergleichsmiete","nach","gesetzlichen","kriterien","kein","allgemeiner","marktpreisrechner","jede","wohnung.","entscheidungsrelevant","mietsteigerungs-","neuvermietungsmodelle","rechtliche","mietgrenze","getrennt","beobachteten","angebotsmieten","modellieren.","vergleichsmieten"]},{"kind":"article","id":"mietsteigerungen-realistisch-modellieren","title":"Mietsteigerungen realistisch modellieren","category":"Vermietung","summary":"Mietsteigerungen sind rechtlich und marktseitig begrenzt.","answer":"Mietsteigerungen sind rechtlich und marktseitig begrenzt. Mietsteigerungen hängen vom Vertragstyp, Mietrecht, Ausgangsniveau und Mieterwechsel ab. Eine pauschale jährliche Wachstumsrate kann rechtlich nicht durchsetzbare Erträge simulieren. Entscheidungsrelevant: Nicht „2 % Mietwachstum“ in jede Periode schreiben, sondern je Mietvertrag begründen, wann und warum eine Anpassung möglich ist.","url":"/wissen/mietsteigerungen-realistisch-modellieren/","keywords":["mietsteigerungen","realistisch","modellieren","rechtlich","marktseitig","begrenzt.","bestandsmieten","mietspiegel","kappungsgrenzen","modernisierung","neuvermietung","müssen","getrennt","betrachtet","werden.","pauschale","wachstumsraten","szenarien.","hängen","vom","vertragstyp","mietrecht","ausgangsniveau","mieterwechsel","ab.","jährliche","wachstumsrate","kann","durchsetzbare","erträge","simulieren.","entscheidungsrelevant","mietwachstum","jede","periode","schreiben","sondern","mietvertrag","begründen","wann","warum","anpassung","möglich","ist.","begrenzt"]},{"kind":"article","id":"mietvertrag-und-ertragssicherheit","title":"Mietvertrag und Ertragssicherheit","category":"Vermietung","summary":"Die vertragliche Miete ist nur dann belastbar, wenn Vertrag und Zahlungshistorie geprüft sind.","answer":"Die vertragliche Miete ist nur dann belastbar, wenn Vertrag und Zahlungshistorie geprüft sind. Der Mietvertrag bestimmt Höhe, Anpassungsmechanismus, Laufzeit, Nebenkostenregelung und weitere Rechte. Diese Punkte beeinflussen die Nachhaltigkeit des Ertrags. Entscheidungsrelevant: Mieterliste und Mietvertrag nicht nur auf Miethöhe prüfen, sondern auf Laufzeit, Index/Staffel, Sicherheiten, Rückstände und Sondervereinbarungen.","url":"/wissen/mietvertrag-und-ertragssicherheit/","keywords":["mietvertrag","ertragssicherheit","vertragliche","miete","dann","belastbar","wenn","vertrag","zahlungshistorie","geprüft","sind.","staffel","index","befristung","nebenabreden","kaution","beeinflussen","ertrag.","bestimmt","höhe","anpassungsmechanismus","laufzeit","nebenkostenregelung","weitere","rechte.","diese","punkte","nachhaltigkeit","ertrags.","entscheidungsrelevant","mieterliste","miethöhe","prüfen","sondern","index/staffel","sicherheiten","rückstände","sondervereinbarungen."]},{"kind":"article","id":"mikrolage-vor-stadtname","title":"Mikrolage vor Stadtname","category":"Marktanalysen","summary":"Straße, Block und fußläufige Umgebung sind oft wichtiger als die Stadt als Ganzes.","answer":"Straße, Block und fußläufige Umgebung sind oft wichtiger als die Stadt als Ganzes. Innerhalb derselben Stadt können Kaufpreis, Miete, Leerstandsrisiko und Zielgruppe straßenweise deutlich variieren. Entscheidungsrelevant: Standortanalyse bis auf Quartier und möglichst Straßen-/Objektebene herunterbrechen; Durchschnittswerte nur zur Plausibilisierung verwenden.","url":"/wissen/mikrolage-vor-stadtname/","keywords":["mikrolage","vor","stadtname","straße","block","fußläufige","umgebung","oft","wichtiger","stadt","ganzes.","öpnv","lärm","nahversorgung","arbeitgeber","schulen","quartiersentwicklung","neubaupipeline","beeinflussen","vermietbarkeit","exit.","innerhalb","derselben","können","kaufpreis","miete","leerstandsrisiko","zielgruppe","straßenweise","deutlich","variieren.","entscheidungsrelevant","standortanalyse","bis","quartier","möglichst","straßen-/objektebene","herunterbrechen","durchschnittswerte","zur","plausibilisierung","verwenden.","ganzes"]},{"kind":"article","id":"modernisierungsumlage","title":"Modernisierungsumlage","category":"Vermietung","summary":"Bestimmte Modernisierungskosten können unter gesetzlichen Voraussetzungen teilweise umgelegt werden.","answer":"Bestimmte Modernisierungskosten können unter gesetzlichen Voraussetzungen teilweise umgelegt werden. Nach § 559 BGB können unter Voraussetzungen 8 % bestimmter Modernisierungskosten auf die Jahresmiete umgelegt werden. Erhaltungsanteile sind herauszurechnen. Entscheidungsrelevant: Investitionsrechnung trennt technische Maßnahme, Erhaltungsanteil, Fördermittel, gesetzlich zulässige Umlage und tatsächlich marktverträgliche Miete.","url":"/wissen/modernisierungsumlage/","keywords":["modernisierungsumlage","bestimmte","modernisierungskosten","können","unter","gesetzlichen","voraussetzungen","teilweise","umgelegt","werden.","abzüge","kappungen","härtefälle","formelle","anforderungen","prüfen.","nach","559","bgb","bestimmter","jahresmiete","erhaltungsanteile","herauszurechnen.","entscheidungsrelevant","investitionsrechnung","trennt","technische","maßnahme","erhaltungsanteil","fördermittel","gesetzlich","zulässige","umlage","tatsächlich","marktverträgliche","miete."]},{"kind":"article","id":"nicht-umlagefahiges-hausgeld","title":"Nicht umlagefähiges Hausgeld","category":"Vermietung","summary":"Nicht umlagefähige Bestandteile des Hausgelds trägt der Eigentümer selbst.","answer":"Nicht umlagefähige Bestandteile des Hausgelds trägt der Eigentümer selbst. Hausgeld umfasst umlagefähige Betriebskosten, nicht umlagefähige Verwaltung-/sonstige Kosten und Zuführungen zur Erhaltungsrücklage. Für die Eigentümerrechnung dürfen diese Bestandteile nicht vermischt werden. Entscheidungsrelevant: Wirtschaftsplan und letzte Jahresabrechnung in einzelne Kostenarten zerlegen, statt pauschal das gesamte Hausgeld von der Miete abzuziehen.","url":"/wissen/nicht-umlagefahiges-hausgeld/","keywords":["umlagefähiges","hausgeld","umlagefähige","bestandteile","hausgelds","trägt","eigentümer","selbst.","typisch","verwalterkosten","instandhaltungsanteile","bestimmte","gemeinschaftskosten.","belastbare","kalkulation","sollten","wirtschaftsplan","letzte","jahresabrechnung","geprüft","werden.","umfasst","betriebskosten","verwaltung-/sonstige","kosten","zuführungen","zur","erhaltungsrücklage.","eigentümerrechnung","dürfen","diese","vermischt","entscheidungsrelevant","einzelne","kostenarten","zerlegen","statt","pauschal","gesamte","miete","abzuziehen.","selbst"]},{"kind":"article","id":"portfolio-risiko-messen","title":"Portfolio-Risiko messen","category":"Kapitalanlage","summary":"Mehrere Objekte reduzieren nicht automatisch Risiko.","answer":"Mehrere Objekte reduzieren nicht automatisch Risiko. Portfolio-Risiko entsteht aus Konzentrationen nach Standort, Objektart, Mieter, Finanzierung, Zinsbindung und technischem Zustand. Entscheidungsrelevant: Konzentrationsgrenzen definieren und Stressszenarien auf Portfolioebene rechnen, etwa gleichzeitiger Zinsanstieg und Leerstand.","url":"/wissen/portfolio-risiko-messen/","keywords":["portfolio-risiko","messen","mehrere","objekte","reduzieren","automatisch","risiko.","standort","mietertyp","finanzierung","zinsbindung","technische","themen","sollten","diversifiziert","portfolioebene","gestresst","werden.","entsteht","aus","konzentrationen","nach","objektart","mieter","technischem","zustand.","entscheidungsrelevant","konzentrationsgrenzen","definieren","stressszenarien","rechnen","etwa","gleichzeitiger","zinsanstieg","leerstand.","portfolio","risiko"]},{"kind":"article","id":"qng-und-effizienzhaus-40","title":"QNG und Effizienzhaus 40","category":"Finanzierung","summary":"KfW 297/298 fördert klimafreundliche Neubauten. Der Kreditrahmen liegt aktuell bei bis zu 100.000 € je Wohneinheit und steigt bei QNG auf bis zu 150.000 € je Wohneinheit.","answer":"Bei KfW 297/298 sind aktuell bis zu 100.000 € Kredit je Wohneinheit für die reguläre klimafreundliche Förderstufe möglich; mit QNG steigt der maximale Kreditbetrag auf bis zu 150.000 € je Wohneinheit. Förderzinsen ändern sich laufend. Die Förderung muss in die Gesamtfinanzierung mit Bankdarlehen und Eigenkapital integriert werden. Entscheidungsrelevant: QNG nicht nur als „150.000-€-Baustein“ betrachten: Förderfähigkeit, Zertifizierungskosten, Zeitplan und Kombination mit dem Restdarlehen müssen wirtschaftlich zusammenpassen.","url":"/wissen/qng-und-effizienzhaus-40/","keywords":["qng","effizienzhaus","kfw","297/298","fördert","klimafreundliche","neubauten.","kreditrahmen","liegt","aktuell","bis","100.000","wohneinheit","steigt","150.000","wohneinheit.","steht","qualitätssiegel","nachhaltiges","gebäude.","beim","kfw-programm","klimafreundlicher","neubau","erhöht","qng-konforme","förderstufe","maximalen","kreditbetrag","technische","nachhaltigkeitsanforderungen","müssen","durch","qualifizierte","experten","bzw.","zertifizierung","nachgewiesen","werden.","kredit","reguläre","möglich","maximale","förderzinsen","ändern","laufend.","förderung","muss","gesamtfinanzierung","bankdarlehen","eigenkapital","integriert","entscheidungsrelevant","150.000-","baustein","betrachten","förderfähigkeit","zertifizierungskosten","zeitplan","kombination"]},{"kind":"article","id":"restnutzungsgutachten-erklart","title":"Restnutzungsgutachten erklärt","category":"Steuern","summary":"Eine nachgewiesene kürzere tatsächliche Nutzungsdauer kann nach § 7 Abs. 4 EStG zu einem höheren linearen AfA-Satz führen. Dafür braucht es einen belastbaren Nachweis – nicht nur eine pauschale Behauptung.","answer":"Beispiel: 400.000 € AfA-Basis, regulär 2 % = 8.000 € AfA pro Jahr. Wird eine tatsächliche Restnutzungsdauer von 25 Jahren steuerlich anerkannt, entspräche das rechnerisch 4 % bzw. 16.000 € pro Jahr. Ob ein Gutachten anerkannt wird, ist eine steuerliche Einzelfallfrage. Entscheidungsrelevant: Restnutzungsdauer nur als belastbare Steuerannahme modellieren, wenn ein fachlich tragfähiger Nachweis realistisch ist und die steuerliche Anerkennung geprüft wurde.","url":"/wissen/restnutzungsgutachten-erklart/","keywords":["restnutzungsgutachten","erklärt","nachgewiesene","kürzere","tatsächliche","nutzungsdauer","kann","nach","abs.","estg","höheren","linearen","afa-satz","führen.","dafür","braucht","belastbaren","nachweis","pauschale","behauptung.","gesetz","erlaubt","gebäuden","unter","bestimmten","voraussetzungen","afa","tatsächlichen","kürzeren","nutzungsdauer.","gutachten","dienen","muss","aber","methodisch","sachlich","tragfähig","sein.","beispiel","400.000","afa-basis","regulär","8.000","pro","jahr.","restnutzungsdauer","jahren","steuerlich","anerkannt","entspräche","rechnerisch","bzw.","16.000","steuerliche","einzelfallfrage.","entscheidungsrelevant","belastbare","steuerannahme","modellieren","wenn"]},{"kind":"article","id":"sachwertverfahren-kompakt","title":"Sachwertverfahren kompakt","category":"Immobilienkauf","summary":"Das Sachwertverfahren betrachtet Herstellungskosten, Alterswertminderung und Marktanpassung.","answer":"Das Sachwertverfahren betrachtet Herstellungskosten, Alterswertminderung und Marktanpassung. Das Sachwertverfahren leitet den Wert aus Bodenwert und Herstellungskosten der baulichen Anlagen unter Berücksichtigung von Alter und Marktanpassung ab. Entscheidungsrelevant: Sachwert nicht isoliert lesen: Marktanpassung und Vergleich mit realen Transaktionen sind entscheidend.","url":"/wissen/sachwertverfahren-kompakt/","keywords":["sachwertverfahren","kompakt","betrachtet","herstellungskosten","alterswertminderung","marktanpassung.","häufig","eigengenutzten","schwer","ertragsorientiert","bewertbaren","objekten","eingesetzt.","leitet","wert","aus","bodenwert","baulichen","anlagen","unter","berücksichtigung","alter","marktanpassung","ab.","entscheidungsrelevant","sachwert","isoliert","lesen","vergleich","realen","transaktionen","entscheidend."]},{"kind":"article","id":"sensitivitatsanalyse-nutzen","title":"Sensitivitätsanalyse nutzen","category":"Kapitalanlage","summary":"Eine Sensitivitätsanalyse zeigt, welche Annahmen das Ergebnis am stärksten verändern.","answer":"Eine Sensitivitätsanalyse zeigt, welche Annahmen das Ergebnis am stärksten verändern. Eine Sensitivitätsanalyse verändert jeweils einzelne Annahmen und zeigt, welche Variablen das Ergebnis besonders treiben. Entscheidungsrelevant: Nicht nur Best-/Base-/Worst-Case benennen, sondern zeigen, ab welchem Zins, welcher Miete oder welchem Kaufpreis die Zielrendite unterschritten wird.","url":"/wissen/sensitivitatsanalyse-nutzen/","keywords":["sensitivitätsanalyse","nutzen","zeigt","welche","annahmen","ergebnis","stärksten","verändern.","typische","treiber","zins","miete","leerstand","capex","exit-faktor.","sichtbar","due","diligence","besonders","tief","sein","muss.","verändert","jeweils","einzelne","variablen","treiben.","entscheidungsrelevant","best-/base-/worst-case","benennen","sondern","zeigen","welchem","welcher","kaufpreis","zielrendite","unterschritten","wird.","verändern"]},{"kind":"article","id":"sonderumlage-als-risiko","title":"Sonderumlage als Risiko","category":"Immobilienkauf","summary":"Sonderumlagen können kurzfristig erhebliches Eigenkapital binden.","answer":"Sonderumlagen können kurzfristig erhebliches Eigenkapital binden. Eine Sonderumlage ist ein zusätzlicher Finanzierungsbeitrag der Wohnungseigentümer, wenn laufende Mittel und Rücklage für Maßnahmen oder Verpflichtungen nicht ausreichen. Entscheidungsrelevant: Protokolle, Beschlusssammlung, Wirtschaftsplan, Rücklagenstand und bekannte Angebote gemeinsam lesen; nicht nur nach „beschlossener Sonderumlage“ fragen.","url":"/wissen/sonderumlage-als-risiko/","keywords":["sonderumlage","risiko","sonderumlagen","können","kurzfristig","erhebliches","eigenkapital","binden.","beschlüsse","protokolle","rücklagenstand","bekannte","schäden","sollten","vor","kauf","geprüft","werden.","zusätzlicher","finanzierungsbeitrag","wohnungseigentümer","wenn","laufende","mittel","rücklage","maßnahmen","verpflichtungen","ausreichen.","entscheidungsrelevant","beschlusssammlung","wirtschaftsplan","angebote","gemeinsam","lesen","nach","beschlossener","fragen.","binden"]},{"kind":"article","id":"spekulationsfrist-im-uberblick","title":"Spekulationsfrist im Überblick","category":"Steuern","summary":"Bei Immobilien im Privatvermögen kann ein Verkauf innerhalb von zehn Jahren nach Anschaffung als privates Veräußerungsgeschäft steuerpflichtig sein. Für Eigennutzung gelten gesetzliche Ausnahmen.","answer":"Bei vermieteten Immobilien im Privatvermögen ist die 10-Jahres-Frist des § 23 EStG zentral. Beispiel: Kaufvertrag 15.09.2026; ein Verkauf nach Ablauf von mehr als zehn Jahren fällt grundsätzlich nicht mehr unter dieses private Veräußerungsgeschäft. Für selbst genutzte Immobilien gibt es gesetzliche Ausnahmen. Das genaue Datum und die Nutzungshistorie sollten steuerlich geprüft werden. Entscheidungsrelevant: Vor einem geplanten Exit innerhalb oder nahe der Zehnjahresgrenze das exakte Anschaffungs- und Verkaufsdatum sowie die Nutzungshistorie steuerlich prüfen.","url":"/wissen/spekulationsfrist-im-uberblick/","keywords":["spekulationsfrist","überblick","immobilien","privatvermögen","kann","verkauf","innerhalb","zehn","jahren","nach","anschaffung","privates","veräußerungsgeschäft","steuerpflichtig","sein.","eigennutzung","gelten","gesetzliche","ausnahmen.","estg","erfasst","grundstücken","grundsätzlich","veräußerungen","denen","zwischen","mehr","jahre","liegen.","ausgenommen","unter","anderem","bestimmte","fälle","ausschließlicher","verkaufsjahr","beiden","vorangegangenen","jahren.","vermieteten","10-jahres-frist","zentral.","beispiel","kaufvertrag","15.09.2026","ablauf","fällt","dieses","private","veräußerungsgeschäft.","selbst","genutzte","gibt","genaue","datum","nutzungshistorie","sollten","steuerlich","geprüft","werden."]},{"kind":"article","id":"staffelmiete-kalkulieren","title":"Staffelmiete kalkulieren","category":"Vermietung","summary":"Staffelmieten machen künftige nominale Mieten planbarer.","answer":"Staffelmieten machen künftige nominale Mieten planbarer. Bei der Staffelmiete werden zukünftige Miethöhen beziehungsweise Erhöhungen in Euro vertraglich festgelegt. Zwischen den Staffeln muss die Miete mindestens ein Jahr unverändert bleiben. Entscheidungsrelevant: Jede Staffel als konkreten Zeitpunkt und Eurobetrag modellieren, nicht als pauschale Wachstumsrate.","url":"/wissen/staffelmiete-kalkulieren/","keywords":["staffelmiete","kalkulieren","staffelmieten","machen","künftige","nominale","mieten","planbarer.","staffeln","müssen","wirksam","vereinbart","sein.","betriebskosten","modernisierungsmöglichkeiten","gesondert","prüfen.","zukünftige","miethöhen","beziehungsweise","erhöhungen","euro","vertraglich","festgelegt.","zwischen","muss","miete","mindestens","jahr","unverändert","bleiben.","entscheidungsrelevant","jede","staffel","konkreten","zeitpunkt","eurobetrag","modellieren","pauschale","wachstumsrate.","planbarer"]},{"kind":"article","id":"steuerlicher-gewinn-und-echter-cashflow","title":"Steuerlicher Gewinn und echter Cashflow","category":"Steuern","summary":"Steuerlicher Überschuss und Bankkontocashflow sind unterschiedliche Größen. AfA mindert den steuerlichen Gewinn ohne Auszahlung; Tilgung belastet die Liquidität, ist aber regelmäßig keine Werbungskostenposition.","answer":"Beispiel: 24.000 € Jahresmiete, 6.000 € laufende Kosten, 10.000 € Schuldzinsen, 8.000 € AfA und 7.000 € Tilgung. Steuerlich ergibt sich vereinfacht 0 € Überschuss (24−6−10−8). Liquiditätsseitig verbleiben vor Steuer aber 1.000 € (24−6−10−7). AfA ist nicht zahlungswirksam, Tilgung schon. Entscheidungsrelevant: Investmententscheidungen auf Cashflow und Gesamtrendite stützen; Steuerwirkung als eigene Ebene modellieren, nicht mit dem operativen Ergebnis vermischen.","url":"/wissen/steuerlicher-gewinn-und-echter-cashflow/","keywords":["steuerlicher","gewinn","echter","cashflow","überschuss","bankkontocashflow","unterschiedliche","größen.","afa","mindert","steuerlichen","ohne","auszahlung","tilgung","belastet","liquidität","aber","regelmäßig","keine","werbungskostenposition.","steuerliche","vermietungsüberschuss","folgt","einnahmen-","werbungskostenregeln.","misst","dagegen","tatsächliche","ein-","auszahlungen.","deshalb","können","beide","größen","dasselbe","objektjahr","richtungen","zeigen.","beispiel","24.000","jahresmiete","6.000","laufende","kosten","10.000","schuldzinsen","8.000","7.000","tilgung.","steuerlich","ergibt","vereinfacht","liquiditätsseitig","verbleiben","vor","steuer","1.000","zahlungswirksam","schon.","entscheidungsrelevant"]},{"kind":"article","id":"tilgung-oder-sondertilgung","title":"Tilgung oder Sondertilgung?","category":"Finanzierung","summary":"Höhere laufende Tilgung und Sondertilgungen reduzieren beide die Restschuld, unterscheiden sich aber in Flexibilität und monatlicher Verpflichtung.","answer":"Bei 300.000 € Darlehen und 4 % Sollzins führt 2 % Anfangstilgung zu 1.500 € Monatsrate; 3 % Tilgung zu 1.750 €. Eine 2-%-Struktur mit zusätzlicher jährlicher Sondertilgung kann die Restschuld stärker senken, erhält aber mehr Flexibilität, sofern die Sondertilgung wirklich geleistet wird. Entscheidungsrelevant: Wer unsichere Einkommensbestandteile hat, kann eine moderate Pflichttilgung mit großzügigem Sondertilgungsrecht bevorzugen. Bei sehr stabilem Überschuss kann eine höhere feste Tilgung die Restschuld planbarer senken.","url":"/wissen/tilgung-oder-sondertilgung/","keywords":["tilgung","sondertilgung","höhere","laufende","sondertilgungen","reduzieren","beide","restschuld","unterscheiden","aber","flexibilität","monatlicher","verpflichtung.","anfangstilgung","erhöht","vertragliche","regelrate","dauerhaft.","sofern","vereinbart","zusätzliche","freiwillige","rückzahlung.","wirtschaftlich","attraktiv","wenn","sichere","zinsersparnis","höher","gewichtet","alternative","verwendung","liquiditätsbedarf.","300.000","darlehen","sollzins","führt","1.500","monatsrate","1.750","2-%-struktur","zusätzlicher","jährlicher","kann","stärker","senken","erhält","mehr","wirklich","geleistet","wird.","entscheidungsrelevant","wer","unsichere","einkommensbestandteile","hat","moderate","pflichttilgung","großzügigem","sondertilgungsrecht"]},{"kind":"article","id":"umlagefahige-betriebskosten","title":"Umlagefähige Betriebskosten","category":"Vermietung","summary":"Umlagefähige Kosten können bei wirksamer Vereinbarung auf Mieter verteilt werden.","answer":"Umlagefähige Kosten können bei wirksamer Vereinbarung auf Mieter verteilt werden. Umlagefähige Betriebskosten richten sich nach Betriebskostenverordnung und Mietvertrag. Nicht jede Eigentümerkostenposition ist automatisch auf den Mieter übertragbar. Entscheidungsrelevant: Letzte Abrechnung und Mietvertrag positionenweise prüfen; Pauschalannahmen wie „Hausgeld komplett umlagefähig“ vermeiden.","url":"/wissen/umlagefahige-betriebskosten/","keywords":["umlagefähige","betriebskosten","kosten","können","wirksamer","vereinbarung","mieter","verteilt","werden.","eigentümer","trägt","dennoch","vorfinanzierung","ausfallrisiko","anteile.","betriebskostenabrechnungen","müssen","formell","inhaltlich","stimmen.","richten","nach","betriebskostenverordnung","mietvertrag.","jede","eigentümerkostenposition","automatisch","übertragbar.","entscheidungsrelevant","letzte","abrechnung","mietvertrag","positionenweise","prüfen","pauschalannahmen","hausgeld","komplett","umlagefähig","vermeiden."]},{"kind":"article","id":"vergleichswertverfahren-kompakt","title":"Vergleichswertverfahren kompakt","category":"Immobilienkauf","summary":"Vergleichspreise ähnlicher Objekte bilden die Grundlage.","answer":"Vergleichspreise ähnlicher Objekte bilden die Grundlage. Das Vergleichswertverfahren leitet den Wert aus Kaufpreisen hinreichend vergleichbarer Grundstücke beziehungsweise Wohnungen ab. Entscheidungsrelevant: Vergleichspreise normalisieren und objektspezifische Abweichungen offen begründen statt einfach Durchschnitt €/m² anzuwenden.","url":"/wissen/vergleichswertverfahren-kompakt/","keywords":["vergleichswertverfahren","kompakt","vergleichspreise","ähnlicher","objekte","bilden","grundlage.","lage","zustand","größe","rechte","verkaufszeitpunkt","müssen","vergleichbar","gemacht","werden.","leitet","wert","aus","kaufpreisen","hinreichend","vergleichbarer","grundstücke","beziehungsweise","wohnungen","ab.","entscheidungsrelevant","normalisieren","objektspezifische","abweichungen","offen","begründen","statt","einfach","durchschnitt","anzuwenden.","grundlage"]},{"kind":"article","id":"vom-rechner-zum-bankgesprach","title":"Vom Rechner zum Bankgespräch","category":"Finanzierung","summary":"Eine gute Immobilienrechnung ist noch keine bankfähige Finanzierung. Für das Bankgespräch müssen Objekt, Einkommen, Eigenkapital und Darlehensstruktur in prüffähige Unterlagen übersetzt werden.","answer":"Vom Rechner zur Bank bedeutet: Kaufpreis und Nebenkosten plausibilisieren, Eigenkapital nachweisen, Einkommen/Bonität dokumentieren, Objektunterlagen vollständig machen und mehrere Darlehensstrukturen vergleichen. Erst dann ist ein Zinsangebot wirklich vergleichbar. Entscheidungsrelevant: Bankangebote auf eine gemeinsame Zielstruktur bringen. Erst danach effektiv vergleichen und die Restschuld am Zinsbindungsende mit in die Entscheidung nehmen.","url":"/wissen/vom-rechner-zum-bankgesprach/","keywords":["vom","rechner","zum","bankgespräch","gute","immobilienrechnung","noch","keine","bankfähige","finanzierung.","müssen","objekt","einkommen","eigenkapital","darlehensstruktur","prüffähige","unterlagen","übersetzt","werden.","bankfähigkeit","entsteht","durch","verbindung","persönlicher","bonität","haushaltsüberschuss","objektwert","sicherheiten","vollständigen","unterlagen.","investmentrechner","kann","wirtschaftlichkeit","beurteilen","ersetzt","aber","weder","kreditprüfung","bankseitige","objektbewertung.","zur","bank","bedeutet","kaufpreis","nebenkosten","plausibilisieren","nachweisen","einkommen/bonität","dokumentieren","objektunterlagen","vollständig","machen","mehrere","darlehensstrukturen","vergleichen.","erst","dann","zinsangebot","wirklich","vergleichbar."]},{"kind":"article","id":"wann-lohnt-sich-ein-mehrfamilienhaus","title":"Wann lohnt sich ein Mehrfamilienhaus?","category":"Immobilienkauf","summary":"Ein Mehrfamilienhaus muss als Gesamtbetrieb aus Mieten, Kosten, Investitionen und Finanzierung betrachtet werden.","answer":"Ein Mehrfamilienhaus muss als Gesamtbetrieb aus Mieten, Kosten, Investitionen und Finanzierung betrachtet werden. Ein Mehrfamilienhaus ist wirtschaftlich attraktiv, wenn Ertrag, CapEx, Finanzierung und Bewirtschaftung auf Portfolioebene tragfähig sind – nicht allein wegen eines niedrigen Kaufpreisfaktors. Entscheidungsrelevant: JNKM, NOI, CapEx-Plan, DSCR/LTV und Mieter-/Einheitenrisiko gemeinsam analysieren; Sollmieten nur bei realistischer rechtlicher Umsetzung einpreisen.","url":"/wissen/wann-lohnt-sich-ein-mehrfamilienhaus/","keywords":["wann","lohnt","mehrfamilienhaus","muss","gesamtbetrieb","aus","mieten","kosten","investitionen","finanzierung","betrachtet","werden.","neben","anfangsrendite","mietstruktur","leerstand","capex","genehmigungslage","energiezustand","exit-fähigkeit","wichtig.","einzelner","multiplikator","reicht","nicht.","wirtschaftlich","attraktiv","wenn","ertrag","bewirtschaftung","portfolioebene","tragfähig","allein","wegen","eines","niedrigen","kaufpreisfaktors.","entscheidungsrelevant","jnkm","noi","capex-plan","dscr/ltv","mieter-/einheitenrisiko","gemeinsam","analysieren","sollmieten","realistischer","rechtlicher","umsetzung","einpreisen."]},{"kind":"article","id":"weg-rucklage-verstehen","title":"WEG-Rücklage verstehen","category":"Vermietung","summary":"Die Erhaltungsrücklage dient künftigen Maßnahmen am Gemeinschaftseigentum.","answer":"Die Erhaltungsrücklage dient künftigen Maßnahmen am Gemeinschaftseigentum. Die Erhaltungsrücklage gehört der Gemeinschaft und dient zukünftigen Maßnahmen am Gemeinschaftseigentum. Der auf eine Wohnung entfallende rechnerische Anteil ist nicht frei verfügbares Guthaben des einzelnen Eigentümers. Entscheidungsrelevant: Rücklage pro Einheit oder m² nur als Plausibilitätsgröße verwenden; entscheidend ist der konkrete CapEx-Bedarf des Gemeinschaftseigentums.","url":"/wissen/weg-rucklage-verstehen/","keywords":["weg-rücklage","verstehen","erhaltungsrücklage","dient","künftigen","maßnahmen","gemeinschaftseigentum.","niedrige","rücklage","kann","anstehenden","arbeiten","sonderumlagen","führen.","protokolle","beschlusssammlung","instandhaltungsplan","daher","zentral.","gehört","gemeinschaft","zukünftigen","wohnung","entfallende","rechnerische","anteil","frei","verfügbares","guthaben","einzelnen","eigentümers.","entscheidungsrelevant","pro","einheit","plausibilitätsgröße","verwenden","entscheidend","konkrete","capex-bedarf","gemeinschaftseigentums.","gemeinschaftseigentum"]},{"kind":"article","id":"wertsteigerung-als-szenario","title":"Wertsteigerung als Szenario","category":"Kapitalanlage","summary":"Wertzuwachs ist unsicher und sollte nicht zur Rettung eines schwachen laufenden Cashflows dienen.","answer":"Wertzuwachs ist unsicher und sollte nicht zur Rettung eines schwachen laufenden Cashflows dienen. Wertsteigerung ist kein laufender Zahlungsstrom und keine garantierte Rendite. Sie hängt von Markt, Mikrolage, Objektqualität, Zinsen und Angebots-/Nachfragedynamik ab. Entscheidungsrelevant: Basisszenario mit 0 % realer Wertsteigerung und zusätzliche positive/negative Szenarien transparent nebeneinanderstellen.","url":"/wissen/wertsteigerung-als-szenario/","keywords":["wertsteigerung","szenario","wertzuwachs","unsicher","sollte","zur","rettung","eines","schwachen","laufenden","cashflows","dienen.","sinnvoll","konservative","basis-","dynamische","szenarien.","beim","exit","fallen","außerdem","verkaufs-","gegebenenfalls","steuerkosten","an.","kein","laufender","zahlungsstrom","keine","garantierte","rendite.","sie","hängt","markt","mikrolage","objektqualität","zinsen","angebots-/nachfragedynamik","ab.","entscheidungsrelevant","basisszenario","realer","zusätzliche","positive/negative","szenarien","transparent","nebeneinanderstellen.","dienen"]},{"kind":"article","id":"wie-berechnet-man-die-eigenkapitalrendite","title":"Wie berechnet man die Eigenkapitalrendite?","category":"Kapitalanlage","summary":"Die Eigenkapitalrendite setzt den jährlichen Vermögenseffekt ins Verhältnis zum tatsächlich eingesetzten Eigenkapital.","answer":"Die Eigenkapitalrendite setzt den jährlichen Vermögenseffekt ins Verhältnis zum tatsächlich eingesetzten Eigenkapital. Eigenkapitalrendite ist nur sinnvoll, wenn klar definiert wird, welcher Ertrag im Zähler steht: laufender Cashflow, Cashflow plus Tilgung oder Total Return inklusive Wertänderung. Entscheidungsrelevant: Cash-on-Cash, Rendite inkl. Tilgung und Total Return getrennt ausweisen – nicht zu einer scheinbar präzisen Zahl vermischen.","url":"/wissen/wie-berechnet-man-die-eigenkapitalrendite/","keywords":["berechnet","man","eigenkapitalrendite","setzt","jährlichen","vermögenseffekt","ins","verhältnis","zum","tatsächlich","eingesetzten","eigenkapital.","cashflow","nach","steuer","tilgung","sofern","bewusst","berücksichtigt","wertveränderung","getrennt","ausgewiesen.","entscheidend","keine","wertsteigerung","garantiert","anzusehen","nebenkosten","sowie","anfangsinvestitionen","vollständig","erfassen.","sinnvoll","wenn","klar","definiert","welcher","ertrag","zähler","steht","laufender","plus","total","return","inklusive","wertänderung.","entscheidungsrelevant","cash-on-cash","rendite","inkl.","ausweisen","scheinbar","präzisen","zahl","vermischen.","eigenkapital"]},{"kind":"article","id":"wohnflachenberechnung-prufen","title":"Wohnflächenberechnung prüfen","category":"Immobilienkauf","summary":"Balkone, Dachschrägen und Nebenflächen werden je nach Regelwerk unterschiedlich berücksichtigt.","answer":"Balkone, Dachschrägen und Nebenflächen werden je nach Regelwerk unterschiedlich berücksichtigt. Wohnfläche beeinflusst Kaufpreis pro m², Miete, Betriebskostenverteilung und teilweise Finanzierung. Fehler können daher mehrfach wirtschaftlich wirken. Entscheidungsrelevant: Bei auffälligen Abweichungen Grundrisse, Flächenberechnung und gegebenenfalls Aufmaß gegeneinander prüfen.","url":"/wissen/wohnflachenberechnung-prufen/","keywords":["wohnflächenberechnung","prüfen","balkone","dachschrägen","nebenflächen","nach","regelwerk","unterschiedlich","berücksichtigt.","flächenabweichungen","können","wert","miete","finanzierung","beeinflussen.","wohnfläche","beeinflusst","kaufpreis","pro","betriebskostenverteilung","teilweise","finanzierung.","fehler","daher","mehrfach","wirtschaftlich","wirken.","entscheidungsrelevant","auffälligen","abweichungen","grundrisse","flächenberechnung","gegebenenfalls","aufmaß","gegeneinander","prüfen.","berücksichtigt"]},{"kind":"article","id":"zinsanderungsstress-testen","title":"Zinsänderungsstress testen","category":"Finanzierung","summary":"Ein Zinsstresstest zeigt, ob die Finanzierung auch dann tragfähig bleibt, wenn die Anschlussfinanzierung deutlich teurer wird.","answer":"Bei 250.000 € Restschuld und 2 % Tilgung ergeben 3,0 % Anschlusszins ca. 1.042 € Monatsrate, 4,5 % ca. 1.354 € und 6,0 % ca. 1.667 €. Die Differenz von rund 625 € pro Monat zwischen 3 % und 6 % sollte bereits heute im Haushalts- oder Objektcashflow berücksichtigt werden. Entscheidungsrelevant: Finanzierung nur dann als robust einstufen, wenn das obere Zinsszenario aus Haushaltsüberschuss oder nachhaltigem Objektüberschuss getragen werden kann.","url":"/wissen/zinsanderungsstress-testen/","keywords":["zinsänderungsstress","testen","zinsstresstest","zeigt","finanzierung","dann","tragfähig","bleibt","wenn","anschlussfinanzierung","deutlich","teurer","wird.","beim","erwartete","restschuld","mehreren","künftigen","sollzinsen","neu","annuitätisch","gerechnet.","test","besonders","aussagekräftig","zusätzlich","einkommen","mieten","kosten","gestresst","werden.","250.000","tilgung","ergeben","anschlusszins","ca.","1.042","monatsrate","1.354","1.667","differenz","rund","625","pro","monat","zwischen","sollte","bereits","heute","haushalts-","objektcashflow","berücksichtigt","entscheidungsrelevant","robust","einstufen","obere","zinsszenario","aus","haushaltsüberschuss","nachhaltigem"]},{"kind":"article","id":"zinsbindung-strategisch-wahlen","title":"Zinsbindung strategisch wählen","category":"Finanzierung","summary":"Zinsbindung ist ein Tausch zwischen aktuellem Preis und künftiger Planungssicherheit. Längere Bindung kann teurer starten, reduziert aber das Terminrisiko der Anschlussfinanzierung.","answer":"10, 15 oder 20 Jahre Zinsbindung sollten nicht nur nach dem heutigen Sollzins gewählt werden. Entscheidend ist, wann welche Restschuld dem Zinsmarkt wieder ausgesetzt wird. Längere Bindungen können einen höheren Startzins haben, kaufen dafür mehr Planungssicherheit. Entscheidungsrelevant: Zinsbindung danach wählen, wie viel Restschuld zu welchem Zeitpunkt vertretbar dem Markt ausgesetzt werden kann – nicht allein nach dem niedrigsten heutigen Sollzins.","url":"/wissen/zinsbindung-strategisch-wahlen/","keywords":["zinsbindung","strategisch","wählen","tausch","zwischen","aktuellem","preis","künftiger","planungssicherheit.","längere","bindung","kann","teurer","starten","reduziert","aber","terminrisiko","anschlussfinanzierung.","sollzinsbindung","bestimmt","lange","vereinbarte","sollzins","festgeschrieben","ist.","sie","identisch","gesamtlaufzeit","darlehens.","nach","ende","verbleibt","häufig","restschuld.","jahre","sollten","heutigen","gewählt","werden.","entscheidend","wann","welche","restschuld","zinsmarkt","wieder","ausgesetzt","wird.","bindungen","können","höheren","startzins","haben","kaufen","dafür","mehr","entscheidungsrelevant","danach","viel","welchem","zeitpunkt"]},{"kind":"lexicon","id":"abgeschlossenheitsbescheinigung","title":"Abgeschlossenheitsbescheinigung","category":"Immobilienkauf","summary":"Bestätigung, dass Einheiten baulich abgeschlossen sind.","answer":"Bestätigung, dass Einheiten baulich abgeschlossen sind. Die Abgeschlossenheitsbescheinigung bestätigt gegenüber dem Grundbuchamt, dass Einheiten baulich hinreichend abgeschlossen sind und ist regelmäßig Voraussetzung für die Begründung von Wohnungs-/Teileigentum.","url":"/lexikon/abgeschlossenheitsbescheinigung/","keywords":["abgeschlossenheitsbescheinigung","bestätigung","einheiten","baulich","abgeschlossen","sind.","bestätigt","gegenüber","grundbuchamt","hinreichend","regelmäßig","voraussetzung","begründung","wohnungs-/teileigentum."]},{"kind":"lexicon","id":"afa","title":"AfA","category":"Steuern","summary":"Absetzung für Abnutzung: steuerliche Verteilung des abschreibungsfähigen Gebäudewerts über die Nutzungsdauer.","answer":"Absetzung für Abnutzung: steuerliche Verteilung des abschreibungsfähigen Gebäudewerts über die Nutzungsdauer. AfA verteilt die steuerlich abschreibungsfähigen Anschaffungs- oder Herstellungskosten eines Gebäudes über die Nutzungsdauer. Grund und Boden ist nicht abschreibbar. Bei Erwerb müssen Kaufpreis und zuordenbare Nebenkosten daher auf Gebäude und Boden aufgeteilt werden.","url":"/lexikon/afa/","keywords":["afa","absetzung","abnutzung","steuerliche","verteilung","abschreibungsfähigen","gebäudewerts","über","nutzungsdauer.","verteilt","steuerlich","anschaffungs-","herstellungskosten","eines","gebäudes","grund","boden","abschreibbar.","erwerb","müssen","kaufpreis","zuordenbare","nebenkosten","daher","gebäude","aufgeteilt","werden."]},{"kind":"lexicon","id":"angebotsmiete","title":"Angebotsmiete","category":"Vermietung","summary":"In Inseraten verlangte Miete; nicht identisch mit tatsächlich vereinbarter Bestandsmiete.","answer":"In Inseraten verlangte Miete; nicht identisch mit tatsächlich vereinbarter Bestandsmiete. Angebotsmiete ist die in Inseraten verlangte Miete und nicht automatisch die tatsächlich vereinbarte Vertragsmiete oder rechtlich zulässige Miete. Sie ist ein Marktindikator mit Selektionsverzerrungen.","url":"/lexikon/angebotsmiete/","keywords":["angebotsmiete","inseraten","verlangte","miete","identisch","tatsächlich","vereinbarter","bestandsmiete.","automatisch","vereinbarte","vertragsmiete","rechtlich","zulässige","miete.","sie","marktindikator","selektionsverzerrungen."]},{"kind":"lexicon","id":"ankaufsprufung","title":"Ankaufsprüfung","category":"Immobilienkauf","summary":"Strukturierte wirtschaftliche, rechtliche, technische und steuerliche Prüfung vor Kauf.","answer":"Strukturierte wirtschaftliche, rechtliche, technische und steuerliche Prüfung vor Kauf. Ankaufsprüfung ist die strukturierte Prüfung eines Immobilienkaufs vor Bindung. Sie verbindet Unterlagen, technische Risiken, Erträge, Kaufpreis, Finanzierung und rechtliche Besonderheiten zu einer belastbaren Entscheidung.","url":"/lexikon/ankaufsprufung/","keywords":["ankaufsprüfung","strukturierte","wirtschaftliche","rechtliche","technische","steuerliche","prüfung","vor","kauf.","eines","immobilienkaufs","bindung.","sie","verbindet","unterlagen","risiken","erträge","kaufpreis","finanzierung","besonderheiten","belastbaren","entscheidung."]},{"kind":"lexicon","id":"annuitat","title":"Annuität","category":"Finanzierung","summary":"Regelmäßig gleichbleibende Rate aus Zins und Tilgung.","answer":"Regelmäßig gleichbleibende Rate aus Zins und Tilgung. Die Annuität ist die regelmäßig gleichbleibende Rate eines klassischen Annuitätendarlehens während der Sollzinsbindung. Sie besteht aus Zins und Tilgung; mit sinkender Restschuld sinkt der Zinsanteil und der Tilgungsanteil steigt.","url":"/lexikon/annuitat/","keywords":["annuität","regelmäßig","gleichbleibende","rate","aus","zins","tilgung.","eines","klassischen","annuitätendarlehens","während","sollzinsbindung.","sie","besteht","tilgung","sinkender","restschuld","sinkt","zinsanteil","tilgungsanteil","steigt."]},{"kind":"lexicon","id":"anschlussfinanzierung","title":"Anschlussfinanzierung","category":"Finanzierung","summary":"Finanzierung der Restschuld nach Ablauf der Zinsbindung.","answer":"Finanzierung der Restschuld nach Ablauf der Zinsbindung. Anschlussfinanzierung ist die Finanzierung der verbleibenden Restschuld nach Ende einer Zinsbindung. Sie kann als Prolongation bei derselben Bank, Umschuldung oder vorab als Forward-Darlehen gestaltet werden.","url":"/lexikon/anschlussfinanzierung/","keywords":["anschlussfinanzierung","finanzierung","restschuld","nach","ablauf","zinsbindung.","verbleibenden","ende","sie","kann","prolongation","derselben","bank","umschuldung","vorab","forward-darlehen","gestaltet","werden."]},{"kind":"lexicon","id":"ausfallwagnis","title":"Ausfallwagnis","category":"Immobilienkauf","summary":"Kalkulatorischer Abschlag für Leerstand und Zahlungsausfälle.","answer":"Kalkulatorischer Abschlag für Leerstand und Zahlungsausfälle. Ausfallwagnis ist die erwartete Belastung aus nicht eingehenden Forderungen oder Erträgen. In Bewertungs- und Investmentmodellen wird es als Risikoabschlag beziehungsweise Kostenkomponente berücksichtigt.","url":"/lexikon/ausfallwagnis/","keywords":["ausfallwagnis","kalkulatorischer","abschlag","leerstand","zahlungsausfälle.","erwartete","belastung","aus","eingehenden","forderungen","erträgen.","bewertungs-","investmentmodellen","risikoabschlag","beziehungsweise","kostenkomponente","berücksichtigt."]},{"kind":"lexicon","id":"baulast","title":"Baulast","category":"Immobilienkauf","summary":"Öffentlich-rechtliche Verpflichtung eines Grundstückseigentümers.","answer":"Öffentlich-rechtliche Verpflichtung eines Grundstückseigentümers. Eine Baulast ist eine öffentlich-rechtliche Verpflichtung eines Grundstückseigentümers gegenüber der Bauaufsichtsbehörde. Sie steht je nach Bundesland im Baulastenverzeichnis und kann Nutzung, Bebaubarkeit oder Wert beeinflussen.","url":"/lexikon/baulast/","keywords":["baulast","öffentlich-rechtliche","verpflichtung","eines","grundstückseigentümers.","grundstückseigentümers","gegenüber","bauaufsichtsbehörde.","sie","steht","nach","bundesland","baulastenverzeichnis","kann","nutzung","bebaubarkeit","wert","beeinflussen."]},{"kind":"lexicon","id":"baunebenkosten","title":"Baunebenkosten","category":"Immobilienkauf","summary":"Planungs-, Genehmigungs- und sonstige Kosten zusätzlich zu Bauleistungen.","answer":"Planungs-, Genehmigungs- und sonstige Kosten zusätzlich zu Bauleistungen. Baunebenkosten sind Kosten rund um Planung, Genehmigung, Finanzierung und Bauabwicklung, die zusätzlich zu den reinen Bauwerkskosten entstehen. Sie werden bei Neubau- und Sanierungsbudgets separat kalkuliert und können einen erheblichen Anteil der Gesamtinvestition ausmachen.","url":"/lexikon/baunebenkosten/","keywords":["baunebenkosten","planungs-","genehmigungs-","sonstige","kosten","zusätzlich","bauleistungen.","rund","planung","genehmigung","finanzierung","bauabwicklung","reinen","bauwerkskosten","entstehen.","sie","neubau-","sanierungsbudgets","separat","kalkuliert","können","erheblichen","anteil","gesamtinvestition","ausmachen."]},{"kind":"lexicon","id":"beleihungsauslauf","title":"Beleihungsauslauf","category":"Finanzierung","summary":"Verhältnis von Darlehen zu bankseitigem Beleihungswert.","answer":"Verhältnis von Darlehen zu bankseitigem Beleihungswert. Der Beleihungsauslauf ist das Verhältnis der relevanten Darlehenssumme zum bankinternen Beleihungswert. Er unterscheidet sich von der einfachen Kaufpreisfinanzierungsquote, weil der Beleihungswert unter dem Kaufpreis liegen kann. Banken nutzen Beleihungsausläufe häufig zur Risikoklassifizierung und Konditionsstaffelung.","url":"/lexikon/beleihungsauslauf/","keywords":["beleihungsauslauf","verhältnis","darlehen","bankseitigem","beleihungswert.","relevanten","darlehenssumme","zum","bankinternen","unterscheidet","einfachen","kaufpreisfinanzierungsquote","weil","beleihungswert","unter","kaufpreis","liegen","kann.","banken","nutzen","beleihungsausläufe","häufig","zur","risikoklassifizierung","konditionsstaffelung."]},{"kind":"lexicon","id":"beleihungswert","title":"Beleihungswert","category":"Finanzierung","summary":"Vorsichtig ermittelter, langfristig erzielbarer Objektwert der Bank.","answer":"Vorsichtig ermittelter, langfristig erzielbarer Objektwert der Bank. Der Beleihungswert ist ein von der Bank vorsichtig und nachhaltig ermittelter Sicherheitenwert, der vom Kaufpreis oder aktuellen Marktwert abweichen kann. Er bildet die Basis für den Beleihungsauslauf.","url":"/lexikon/beleihungswert/","keywords":["beleihungswert","vorsichtig","ermittelter","langfristig","erzielbarer","objektwert","bank.","bank","nachhaltig","sicherheitenwert","vom","kaufpreis","aktuellen","marktwert","abweichen","kann.","bildet","basis","beleihungsauslauf."]},{"kind":"lexicon","id":"bereitstellungszins","title":"Bereitstellungszins","category":"Finanzierung","summary":"Zins auf noch nicht abgerufene Darlehensteile nach einer Freiphase.","answer":"Zins auf noch nicht abgerufene Darlehensteile nach einer Freiphase. Bereitstellungszinsen sind Entgelte auf noch nicht abgerufene Darlehensteile nach Ablauf der bereitstellungszinsfreien Zeit. Sie sind besonders bei Neubau, Bauträgerzahlung und längeren Sanierungsphasen relevant.","url":"/lexikon/bereitstellungszins/","keywords":["bereitstellungszins","zins","noch","abgerufene","darlehensteile","nach","freiphase.","bereitstellungszinsen","entgelte","ablauf","bereitstellungszinsfreien","zeit.","sie","besonders","neubau","bauträgerzahlung","längeren","sanierungsphasen","relevant."]},{"kind":"lexicon","id":"betriebskosten","title":"Betriebskosten","category":"Vermietung","summary":"Laufende Kosten des bestimmungsgemäßen Gebrauchs.","answer":"Laufende Kosten des bestimmungsgemäßen Gebrauchs. Betriebskosten sind laufende Kosten des bestimmungsgemäßen Gebrauchs eines Gebäudes/Grundstücks. Welche Positionen auf Wohnraummieter umgelegt werden können, richtet sich nach Betriebskostenverordnung und wirksamer mietvertraglicher Vereinbarung.","url":"/lexikon/betriebskosten/","keywords":["betriebskosten","laufende","kosten","bestimmungsgemäßen","gebrauchs.","gebrauchs","eines","gebäudes/grundstücks.","welche","positionen","wohnraummieter","umgelegt","können","richtet","nach","betriebskostenverordnung","wirksamer","mietvertraglicher","vereinbarung."]},{"kind":"lexicon","id":"bewirtschaftungskosten","title":"Bewirtschaftungskosten","category":"Immobilienkauf","summary":"Kosten für Verwaltung, Betrieb, Instandhaltung und Mietausfall.","answer":"Kosten für Verwaltung, Betrieb, Instandhaltung und Mietausfall. Bewirtschaftungskosten sind laufende Kosten der Nutzung und Verwaltung eines Grundstücks, etwa Verwaltung, Instandhaltung und Mietausfallwagnis nach der jeweiligen Bewertungsdefinition. Sie reduzieren den nachhaltig verfügbaren Ertrag.","url":"/lexikon/bewirtschaftungskosten/","keywords":["bewirtschaftungskosten","kosten","verwaltung","betrieb","instandhaltung","mietausfall.","laufende","nutzung","eines","grundstücks","etwa","mietausfallwagnis","nach","jeweiligen","bewertungsdefinition.","sie","reduzieren","nachhaltig","verfügbaren","ertrag."]},{"kind":"lexicon","id":"bodenrichtwert","title":"Bodenrichtwert","category":"Immobilienkauf","summary":"Durchschnittlicher Bodenwert eines räumlich abgegrenzten Richtwertgebiets.","answer":"Durchschnittlicher Bodenwert eines räumlich abgegrenzten Richtwertgebiets. Bodenrichtwert ist ein durchschnittlicher Lagewert des Bodens für eine Bodenrichtwertzone. Er ist kein verbindlicher Einzelgrundstückswert; Nutzung, Größe, Zuschnitt, Erschließung und weitere Merkmale können Anpassungen erforderlich machen.","url":"/lexikon/bodenrichtwert/","keywords":["bodenrichtwert","durchschnittlicher","bodenwert","eines","räumlich","abgegrenzten","richtwertgebiets.","lagewert","bodens","bodenrichtwertzone.","kein","verbindlicher","einzelgrundstückswert","nutzung","größe","zuschnitt","erschließung","weitere","merkmale","können","anpassungen","erforderlich","machen."]},{"kind":"lexicon","id":"bodenwert","title":"Bodenwert","category":"Immobilienkauf","summary":"Wert des unbebauten Grundstücks.","answer":"Wert des unbebauten Grundstücks. Bodenwert ist der Wert des Grundstücksbodens ohne Gebäude. Er kann aus geeigneten Vergleichsdaten oder Bodenrichtwerten unter objektspezifischen Anpassungen abgeleitet werden.","url":"/lexikon/bodenwert/","keywords":["bodenwert","wert","unbebauten","grundstücks.","grundstücksbodens","ohne","gebäude.","kann","aus","geeigneten","vergleichsdaten","bodenrichtwerten","unter","objektspezifischen","anpassungen","abgeleitet","werden."]},{"kind":"lexicon","id":"bonitat","title":"Bonität","category":"Finanzierung","summary":"Einschätzung der Fähigkeit und Bereitschaft, Verpflichtungen zu erfüllen.","answer":"Einschätzung der Fähigkeit und Bereitschaft, Verpflichtungen zu erfüllen. Bonität beschreibt die Fähigkeit und Bereitschaft eines Schuldners, finanzielle Verpflichtungen vertragsgemäß zu erfüllen. Banken beurteilen dafür Einkommen, Vermögen, Verpflichtungen, Zahlungsverhalten und weitere Risikomerkmale.","url":"/lexikon/bonitat/","keywords":["bonität","einschätzung","fähigkeit","bereitschaft","verpflichtungen","erfüllen.","beschreibt","eines","schuldners","finanzielle","vertragsgemäß","banken","beurteilen","dafür","einkommen","vermögen","zahlungsverhalten","weitere","risikomerkmale."]},{"kind":"lexicon","id":"bruttogrundflache","title":"Bruttogrundfläche","category":"Immobilienkauf","summary":"Gesamtheit bestimmter Grundflächen eines Bauwerks nach Norm.","answer":"Gesamtheit bestimmter Grundflächen eines Bauwerks nach Norm. Die Bruttogrundfläche ist eine Flächengröße aus dem Bau-/Bewertungsbereich und umfasst deutlich mehr als die Wohnfläche, unter anderem konstruktive Flächen. Sie ist für €/m²-Wohnungsvergleiche nicht austauschbar mit Wohnfläche.","url":"/lexikon/bruttogrundflache/","keywords":["bruttogrundfläche","gesamtheit","bestimmter","grundflächen","eines","bauwerks","nach","norm.","flächengröße","aus","bau-/bewertungsbereich","umfasst","deutlich","mehr","wohnfläche","unter","anderem","konstruktive","flächen.","sie","wohnungsvergleiche","austauschbar","wohnfläche."]},{"kind":"lexicon","id":"bruttomietrendite","title":"Bruttomietrendite","category":"Kapitalanlage","summary":"Jahresnettokaltmiete geteilt durch Kaufpreis.","answer":"Jahresnettokaltmiete geteilt durch Kaufpreis. Die Bruttomietrendite ist eine schnelle Screeningkennzahl aus Jahresnettokaltmiete und Kaufpreis. Sie berücksichtigt weder Kaufnebenkosten noch laufende Eigentümerkosten oder Finanzierung.","url":"/lexikon/bruttomietrendite/","keywords":["bruttomietrendite","jahresnettokaltmiete","geteilt","durch","kaufpreis.","schnelle","screeningkennzahl","aus","sie","berücksichtigt","weder","kaufnebenkosten","noch","laufende","eigentümerkosten","finanzierung."]},{"kind":"lexicon","id":"capex","title":"Capex","category":"Kapitalanlage","summary":"Größere, wert- oder nutzungsdauerrelevante Investitionen.","answer":"Größere, wert- oder nutzungsdauerrelevante Investitionen. Größere, wert- oder nutzungsdauerrelevante Investitionen. Capex ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/capex/","keywords":["capex","größere","wert-","nutzungsdauerrelevante","investitionen.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"cash-on-cash-rendite","title":"Cash-on-Cash-Rendite","category":"Kapitalanlage","summary":"Laufender Cashflow im Verhältnis zum eingesetzten Eigenkapital.","answer":"Laufender Cashflow im Verhältnis zum eingesetzten Eigenkapital. Laufender Cashflow im Verhältnis zum eingesetzten Eigenkapital. Cash-on-Cash-Rendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/cash-on-cash-rendite/","keywords":["cash-on-cash-rendite","laufender","cashflow","verhältnis","zum","eingesetzten","eigenkapital.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"cashflow","title":"Cashflow","category":"Kapitalanlage","summary":"Liquiditätsüberschuss oder -bedarf einer Periode.","answer":"Liquiditätsüberschuss oder -bedarf einer Periode. Cashflow bildet tatsächliche Ein- und Auszahlungen ab. Bei Immobilien sollte zwischen operativem Cashflow vor Finanzierung und Cashflow nach Kapitaldienst unterschieden werden. Tilgung belastet den Cashflow, ist aber gleichzeitig Vermögensumschichtung in das Objekt.","url":"/lexikon/cashflow/","keywords":["cashflow","liquiditätsüberschuss","bedarf","periode.","bildet","tatsächliche","ein-","auszahlungen","ab.","immobilien","sollte","zwischen","operativem","vor","finanzierung","nach","kapitaldienst","unterschieden","werden.","tilgung","belastet","aber","gleichzeitig","vermögensumschichtung","objekt."]},{"kind":"lexicon","id":"courtage","title":"Courtage","category":"Immobilienkauf","summary":"Maklervergütung.","answer":"Maklervergütung. Courtage ist die erfolgsabhängige Maklervergütung. Bei Kaufverträgen über Wohnungen und Einfamilienhäuser mit Verbraucherbeteiligung greifen die besonderen §§ 656a–656d BGB: Bei Doppeltätigkeit müssen sich beide Parteien in gleicher Höhe verpflichten; bei einseitigem Maklerauftrag kann eine Kostenabwälzung auf die andere Partei nur unter den gesetzlichen Voraussetzungen erfolgen. Diese Sonderregeln gelten nicht automatisch für Mehrfamilienhäuser, Gewerbeimmobilien oder Grundstücke. Eine allgemeine gesetzliche Provisionsobergrenze je Bundesland für Immobilienverkäufe existiert nicht; regionale Marktüblichkeiten sind keine gesetzlichen Höchstsätze.","url":"/lexikon/courtage/","keywords":["courtage","maklervergütung.","erfolgsabhängige","kaufverträgen","über","wohnungen","einfamilienhäuser","verbraucherbeteiligung","greifen","besonderen","656a","656d","bgb","doppeltätigkeit","müssen","beide","parteien","gleicher","höhe","verpflichten","einseitigem","maklerauftrag","kann","kostenabwälzung","andere","partei","unter","gesetzlichen","voraussetzungen","erfolgen.","diese","sonderregeln","gelten","automatisch","mehrfamilienhäuser","gewerbeimmobilien","grundstücke.","allgemeine","gesetzliche","provisionsobergrenze","bundesland","immobilienverkäufe","existiert","regionale","marktüblichkeiten","keine","höchstsätze."]},{"kind":"lexicon","id":"debt-service","title":"Debt Service","category":"Immobilienkauf","summary":"Summe aus Zins und Tilgung.","answer":"Summe aus Zins und Tilgung. Debt Service beziehungsweise Kapitaldienst umfasst die periodischen Zahlungen an Fremdkapitalgeber, typischerweise Zins und Tilgung. Bei endfälligen oder variabel strukturierten Darlehen kann der Zahlungsstrom abweichen.","url":"/lexikon/debt-service/","keywords":["debt","service","summe","aus","zins","tilgung.","beziehungsweise","kapitaldienst","umfasst","periodischen","zahlungen","fremdkapitalgeber","typischerweise","endfälligen","variabel","strukturierten","darlehen","kann","zahlungsstrom","abweichen."]},{"kind":"lexicon","id":"dscr","title":"DSCR","category":"Finanzierung","summary":"Verhältnis des zur Verfügung stehenden Überschusses zum Schuldendienst.","answer":"Verhältnis des zur Verfügung stehenden Überschusses zum Schuldendienst. Der Debt Service Coverage Ratio misst, wie oft ein definierter verfügbarer Ertrag den Kapitaldienst aus Zins und Tilgung deckt. Die Aussage hängt stark davon ab, welche Ergebnisgröße im Zähler verwendet wird.","url":"/lexikon/dscr/","keywords":["dscr","verhältnis","zur","verfügung","stehenden","überschusses","zum","schuldendienst.","debt","service","coverage","ratio","misst","oft","definierter","verfügbarer","ertrag","kapitaldienst","aus","zins","tilgung","deckt.","aussage","hängt","stark","davon","welche","ergebnisgröße","zähler","verwendet","wird."]},{"kind":"lexicon","id":"due-diligence","title":"Due Diligence","category":"Immobilienkauf","summary":"Systematische Prüfung eines Investments.","answer":"Systematische Prüfung eines Investments. Due Diligence ist die strukturierte Prüfung einer Transaktion vor Abschluss. Bei Immobilien umfasst sie je nach Objekt rechtliche, technische, wirtschaftliche, steuerliche und finanzielle Aspekte.","url":"/lexikon/due-diligence/","keywords":["due","diligence","systematische","prüfung","eines","investments.","strukturierte","transaktion","vor","abschluss.","immobilien","umfasst","sie","nach","objekt","rechtliche","technische","wirtschaftliche","steuerliche","finanzielle","aspekte."]},{"kind":"lexicon","id":"eigenkapital","title":"Eigenkapital","category":"Immobilienkauf","summary":"Eigene Mittel, die in Kauf und Nebenkosten eingebracht werden.","answer":"Eigene Mittel, die in Kauf und Nebenkosten eingebracht werden. Eigenkapital umfasst die für den Erwerb eingesetzten eigenen Mittel. Mehr Eigenkapital reduziert Darlehen und kann den Beleihungsauslauf senken; dadurch kann sich die Bankkondition verbessern. Gleichzeitig sinkt die frei verfügbare Liquiditätsreserve.","url":"/lexikon/eigenkapital/","keywords":["eigenkapital","eigene","mittel","kauf","nebenkosten","eingebracht","werden.","umfasst","erwerb","eingesetzten","eigenen","mittel.","mehr","reduziert","darlehen","kann","beleihungsauslauf","senken","dadurch","bankkondition","verbessern.","gleichzeitig","sinkt","frei","verfügbare","liquiditätsreserve."]},{"kind":"lexicon","id":"eigenkapitalrendite","title":"Eigenkapitalrendite","category":"Kapitalanlage","summary":"Vermögenseffekt oder Ertrag im Verhältnis zum eingesetzten Eigenkapital.","answer":"Vermögenseffekt oder Ertrag im Verhältnis zum eingesetzten Eigenkapital. Eigenkapitalrendite setzt einen definierten Ertrag ins Verhältnis zum eingesetzten Eigenkapital. Cashflow, Tilgung und Wertänderung sollten getrennt ausgewiesen werden, weil sie wirtschaftlich unterschiedliche Komponenten sind.","url":"/lexikon/eigenkapitalrendite/","keywords":["eigenkapitalrendite","vermögenseffekt","ertrag","verhältnis","zum","eingesetzten","eigenkapital.","setzt","definierten","ins","cashflow","tilgung","wertänderung","sollten","getrennt","ausgewiesen","weil","sie","wirtschaftlich","unterschiedliche","komponenten","sind."]},{"kind":"lexicon","id":"erbbaurecht","title":"Erbbaurecht","category":"Immobilienkauf","summary":"Zeitlich befristetes Recht, auf fremdem Grund ein Bauwerk zu haben.","answer":"Zeitlich befristetes Recht, auf fremdem Grund ein Bauwerk zu haben. Beim Erbbaurecht werden Gebäude und Grundstückseigentum rechtlich getrennt: Der Erbbauberechtigte nutzt das Grundstück für eine bestimmte Laufzeit und zahlt typischerweise Erbbauzins. Restlaufzeit, Anpassungsklauseln und Heimfallregelungen beeinflussen Wert und Finanzierung.","url":"/lexikon/erbbaurecht/","keywords":["erbbaurecht","zeitlich","befristetes","recht","fremdem","grund","bauwerk","haben.","beim","gebäude","grundstückseigentum","rechtlich","getrennt","erbbauberechtigte","nutzt","grundstück","bestimmte","laufzeit","zahlt","typischerweise","erbbauzins.","restlaufzeit","anpassungsklauseln","heimfallregelungen","beeinflussen","wert","finanzierung."]},{"kind":"lexicon","id":"erbbauzins","title":"Erbbauzins","category":"Finanzierung","summary":"Regelmäßiges Entgelt für ein Erbbaurecht.","answer":"Regelmäßiges Entgelt für ein Erbbaurecht. Erbbauzins ist das regelmäßig zu zahlende Entgelt des Erbbauberechtigten an den Grundstückseigentümer. Höhe und Anpassungsmechanismus ergeben sich aus dem Erbbaurechtsvertrag.","url":"/lexikon/erbbauzins/","keywords":["erbbauzins","regelmäßiges","entgelt","erbbaurecht.","regelmäßig","zahlende","erbbauberechtigten","grundstückseigentümer.","höhe","anpassungsmechanismus","ergeben","aus","erbbaurechtsvertrag."]},{"kind":"lexicon","id":"erhaltungsrucklage","title":"Erhaltungsrücklage","category":"Vermietung","summary":"Von einer WEG angesparte Mittel für Gemeinschaftseigentum.","answer":"Von einer WEG angesparte Mittel für Gemeinschaftseigentum. Die Erhaltungsrücklage ist Gemeinschaftsvermögen der WEG für künftige Maßnahmen am Gemeinschaftseigentum. Der rechnerisch auf eine Wohnung entfallende Anteil ist kein frei auszahlbares Guthaben des einzelnen Eigentümers.","url":"/lexikon/erhaltungsrucklage/","keywords":["erhaltungsrücklage","weg","angesparte","mittel","gemeinschaftseigentum.","gemeinschaftsvermögen","künftige","maßnahmen","rechnerisch","wohnung","entfallende","anteil","kein","frei","auszahlbares","guthaben","einzelnen","eigentümers."]},{"kind":"lexicon","id":"ertragswert","title":"Ertragswert","category":"Immobilienkauf","summary":"Aus nachhaltig erzielbaren Erträgen abgeleiteter Wert.","answer":"Aus nachhaltig erzielbaren Erträgen abgeleiteter Wert. Der Ertragswert ist ein im Ertragswertverfahren abgeleiteter Grundstückswert, der wesentlich auf nachhaltig erzielbaren Erträgen, Bewirtschaftungskosten, Liegenschaftszins und Restnutzungsdauer beruht.","url":"/lexikon/ertragswert/","keywords":["ertragswert","aus","nachhaltig","erzielbaren","erträgen","abgeleiteter","wert.","ertragswertverfahren","grundstückswert","wesentlich","bewirtschaftungskosten","liegenschaftszins","restnutzungsdauer","beruht."]},{"kind":"lexicon","id":"exit-faktor","title":"Exit-Faktor","category":"Kapitalanlage","summary":"Beim Verkauf angenommener Kaufpreisfaktor.","answer":"Beim Verkauf angenommener Kaufpreisfaktor. Beim Verkauf angenommener Kaufpreisfaktor. Exit-Faktor ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/exit-faktor/","keywords":["exit-faktor","beim","verkauf","angenommener","kaufpreisfaktor.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"exit","title":"Exit","category":"Kapitalanlage","summary":"Geplanter Verkauf oder anderweitiger Ausstieg aus dem Investment.","answer":"Geplanter Verkauf oder anderweitiger Ausstieg aus dem Investment. Geplanter Verkauf oder anderweitiger Ausstieg aus dem Investment. Exit ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/exit/","keywords":["exit","geplanter","verkauf","anderweitiger","ausstieg","aus","investment.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"finanzierungsquote","title":"Finanzierungsquote","category":"Finanzierung","summary":"Anteil einer gewählten Bezugsgröße, der durch Darlehen finanziert wird.","answer":"Anteil einer gewählten Bezugsgröße, der durch Darlehen finanziert wird. Die Finanzierungsquote setzt die Darlehenssumme ins Verhältnis zu einer definierten Investitionsbasis, meist Kaufpreis oder Gesamtinvestition. Sie ist von LTV und Beleihungsauslauf zu unterscheiden, weil dort andere Wertansätze im Nenner stehen können.","url":"/lexikon/finanzierungsquote/","keywords":["finanzierungsquote","anteil","gewählten","bezugsgröße","durch","darlehen","finanziert","wird.","setzt","darlehenssumme","ins","verhältnis","definierten","investitionsbasis","meist","kaufpreis","gesamtinvestition.","sie","ltv","beleihungsauslauf","unterscheiden","weil","dort","andere","wertansätze","nenner","stehen","können."]},{"kind":"lexicon","id":"flurstuck","title":"Flurstück","category":"Immobilienkauf","summary":"Amtlich vermessener Teil der Erdoberfläche.","answer":"Amtlich vermessener Teil der Erdoberfläche. Ein Flurstück ist die kleinste im Liegenschaftskataster geführte Buchungseinheit eines Grundstücks. Ein Grundstück im Grundbuch kann aus einem oder mehreren Flurstücken bestehen.","url":"/lexikon/flurstuck/","keywords":["flurstück","amtlich","vermessener","teil","erdoberfläche.","kleinste","liegenschaftskataster","geführte","buchungseinheit","eines","grundstücks.","grundstück","grundbuch","kann","aus","mehreren","flurstücken","bestehen."]},{"kind":"lexicon","id":"forward-darlehen","title":"Forward-Darlehen","category":"Finanzierung","summary":"Heute vereinbarte Anschlussfinanzierung mit späterer Auszahlung.","answer":"Heute vereinbarte Anschlussfinanzierung mit späterer Auszahlung. Ein Forward-Darlehen ist eine heute vereinbarte Anschlussfinanzierung mit zukünftiger Auszahlung. Der Darlehensnehmer sichert den Zins vor Ende der bestehenden Bindung; dafür kann ein Forward-Aufschlag anfallen. Vorlaufzeiten von mehreren Jahren, häufig bis etwa fünf Jahre, sind marktüblich, aber bankabhängig.","url":"/lexikon/forward-darlehen/","keywords":["forward-darlehen","heute","vereinbarte","anschlussfinanzierung","späterer","auszahlung.","zukünftiger","darlehensnehmer","sichert","zins","vor","ende","bestehenden","bindung","dafür","kann","forward-aufschlag","anfallen.","vorlaufzeiten","mehreren","jahren","häufig","bis","etwa","fünf","jahre","marktüblich","aber","bankabhängig."]},{"kind":"lexicon","id":"fremdkapitalhebel","title":"Fremdkapitalhebel","category":"Kapitalanlage","summary":"Veränderung der Eigenkapitalrendite durch Einsatz von Fremdkapital.","answer":"Veränderung der Eigenkapitalrendite durch Einsatz von Fremdkapital. Veränderung der Eigenkapitalrendite durch Einsatz von Fremdkapital. Fremdkapitalhebel ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/fremdkapitalhebel/","keywords":["fremdkapitalhebel","veränderung","eigenkapitalrendite","durch","einsatz","fremdkapital.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"gebaudeanteil","title":"Gebäudeanteil","category":"Immobilienkauf","summary":"Anteil des Kaufpreises, der dem Gebäude statt Grund und Boden zugeordnet wird.","answer":"Anteil des Kaufpreises, der dem Gebäude statt Grund und Boden zugeordnet wird. Gebäudeanteil bezeichnet den Teil des Gesamtwerts beziehungsweise der Anschaffungskosten, der wirtschaftlich auf das Gebäude entfällt. Für die Gebäude-AfA ist die Abgrenzung zum nicht abschreibbaren Grund und Boden zentral.","url":"/lexikon/gebaudeanteil/","keywords":["gebäudeanteil","anteil","kaufpreises","gebäude","statt","grund","boden","zugeordnet","wird.","bezeichnet","teil","gesamtwerts","beziehungsweise","anschaffungskosten","wirtschaftlich","entfällt.","gebäude-afa","abgrenzung","zum","abschreibbaren","zentral."]},{"kind":"lexicon","id":"gemeinschaftseigentum","title":"Gemeinschaftseigentum","category":"Immobilienkauf","summary":"Teile einer WEG, die allen Eigentümern gemeinsam gehören.","answer":"Teile einer WEG, die allen Eigentümern gemeinsam gehören. Gemeinschaftseigentum sind Gebäudeteile und Grundstücksbestandteile, die allen Wohnungseigentümern gemeinschaftlich gehören oder zwingend gemeinschaftlich sein müssen. Maßnahmen werden über die WEG entschieden und finanziert.","url":"/lexikon/gemeinschaftseigentum/","keywords":["gemeinschaftseigentum","teile","weg","allen","eigentümern","gemeinsam","gehören.","gebäudeteile","grundstücksbestandteile","wohnungseigentümern","gemeinschaftlich","gehören","zwingend","sein","müssen.","maßnahmen","über","entschieden","finanziert."]},{"kind":"lexicon","id":"gesamtinvestition","title":"Gesamtinvestition","category":"Immobilienkauf","summary":"Kaufpreis plus Nebenkosten und Anfangsinvestitionen.","answer":"Kaufpreis plus Nebenkosten und Anfangsinvestitionen. Gesamtinvestition umfasst den gesamten wirtschaftlich eingesetzten Kapitalbetrag für Erwerb und Herstellung der Nutzbarkeit, nicht nur den notariellen Kaufpreis.","url":"/lexikon/gesamtinvestition/","keywords":["gesamtinvestition","kaufpreis","plus","nebenkosten","anfangsinvestitionen.","umfasst","gesamten","wirtschaftlich","eingesetzten","kapitalbetrag","erwerb","herstellung","nutzbarkeit","notariellen","kaufpreis."]},{"kind":"lexicon","id":"grundbuch","title":"Grundbuch","category":"Immobilienkauf","summary":"Öffentliches Register der Grundstücksrechte.","answer":"Öffentliches Register der Grundstücksrechte. Das Grundbuch dokumentiert Eigentum und dingliche Rechte an Grundstücken. Abteilung I enthält Eigentümer, Abteilung II unter anderem Lasten/Beschränkungen und Abteilung III Grundpfandrechte.","url":"/lexikon/grundbuch/","keywords":["grundbuch","öffentliches","register","grundstücksrechte.","dokumentiert","eigentum","dingliche","rechte","grundstücken.","abteilung","enthält","eigentümer","unter","anderem","lasten/beschränkungen","iii","grundpfandrechte."]},{"kind":"lexicon","id":"grunderwerbsteuer","title":"Grunderwerbsteuer","category":"Steuern","summary":"Landessteuer beim Erwerb inländischer Grundstücke.","answer":"Landessteuer beim Erwerb inländischer Grundstücke. Grunderwerbsteuer fällt bei steuerbaren Grundstückserwerben an und wird von den Ländern mit unterschiedlichen Steuersätzen erhoben. Sie ist regelmäßig nicht Teil der Gebäude-AfA, sondern wird anteilig den Anschaffungskosten von Grund/Boden und Gebäude zugerechnet.","url":"/lexikon/grunderwerbsteuer/","keywords":["grunderwerbsteuer","landessteuer","beim","erwerb","inländischer","grundstücke.","fällt","steuerbaren","grundstückserwerben","ländern","unterschiedlichen","steuersätzen","erhoben.","sie","regelmäßig","teil","gebäude-afa","sondern","anteilig","anschaffungskosten","grund/boden","gebäude","zugerechnet."]},{"kind":"lexicon","id":"grundschuld","title":"Grundschuld","category":"Finanzierung","summary":"Grundpfandrecht zur Kreditsicherung.","answer":"Grundpfandrecht zur Kreditsicherung. Die Grundschuld ist ein dingliches Sicherungsrecht im Grundbuch, das Banken typischerweise zur Absicherung eines Immobiliendarlehens nutzen. Sie ist rechtlich vom Darlehen getrennt und bleibt ohne Löschung auch nach Tilgung im Grundbuch bestehen.","url":"/lexikon/grundschuld/","keywords":["grundschuld","grundpfandrecht","zur","kreditsicherung.","dingliches","sicherungsrecht","grundbuch","banken","typischerweise","absicherung","eines","immobiliendarlehens","nutzen.","sie","rechtlich","vom","darlehen","getrennt","bleibt","ohne","löschung","nach","tilgung","bestehen."]},{"kind":"lexicon","id":"grundsteuer","title":"Grundsteuer","category":"Steuern","summary":"Laufende Steuer auf Grundbesitz.","answer":"Laufende Steuer auf Grundbesitz. Grundsteuer ist eine laufende Objektsteuer auf Grundbesitz. Bei vermietetem Wohnraum kann sie bei wirksamer Betriebskostenvereinbarung grundsätzlich umlagefähig sein.","url":"/lexikon/grundsteuer/","keywords":["grundsteuer","laufende","steuer","grundbesitz.","objektsteuer","vermietetem","wohnraum","kann","sie","wirksamer","betriebskostenvereinbarung","grundsätzlich","umlagefähig","sein."]},{"kind":"lexicon","id":"hausgeld","title":"Hausgeld","category":"Vermietung","summary":"Monatliche Vorauszahlung des Wohnungseigentümers an die WEG.","answer":"Monatliche Vorauszahlung des Wohnungseigentümers an die WEG. Hausgeld ist der monatliche Vorschuss eines Wohnungseigentümers an die WEG. Es umfasst typischerweise Betriebskosten, Verwaltung und Zuführung zur Erhaltungsrücklage; deshalb ist es nicht mit „Nebenkosten des Mieters“ gleichzusetzen.","url":"/lexikon/hausgeld/","keywords":["hausgeld","monatliche","vorauszahlung","wohnungseigentümers","weg.","vorschuss","eines","umfasst","typischerweise","betriebskosten","verwaltung","zuführung","zur","erhaltungsrücklage","deshalb","nebenkosten","mieters","gleichzusetzen."]},{"kind":"lexicon","id":"hebelwirkung","title":"Hebelwirkung","category":"Kapitalanlage","summary":"Wirkung von Fremdkapital auf Eigenkapitalergebnis und Risiko.","answer":"Wirkung von Fremdkapital auf Eigenkapitalergebnis und Risiko. Wirkung von Fremdkapital auf Eigenkapitalergebnis und Risiko. Hebelwirkung ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/hebelwirkung/","keywords":["hebelwirkung","wirkung","fremdkapital","eigenkapitalergebnis","risiko.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"indexmiete","title":"Indexmiete","category":"Vermietung","summary":"Miete mit vertraglicher Kopplung an den Verbraucherpreisindex.","answer":"Miete mit vertraglicher Kopplung an den Verbraucherpreisindex. Bei der Indexmiete wird die Mietentwicklung an den vom Statistischen Bundesamt ermittelten Verbraucherpreisindex gekoppelt. Die Miete ändert sich nicht automatisch; die gesetzlich vorgeschriebene Erklärung ist erforderlich. Während der Geltung muss die Miete grundsätzlich mindestens ein Jahr unverändert bleiben.","url":"/lexikon/indexmiete/","keywords":["indexmiete","miete","vertraglicher","kopplung","verbraucherpreisindex.","mietentwicklung","vom","statistischen","bundesamt","ermittelten","verbraucherpreisindex","gekoppelt.","ändert","automatisch","gesetzlich","vorgeschriebene","erklärung","erforderlich.","während","geltung","muss","grundsätzlich","mindestens","jahr","unverändert","bleiben."]},{"kind":"lexicon","id":"instandhaltung","title":"Instandhaltung","category":"Immobilienkauf","summary":"Maßnahmen zum Erhalt des bestimmungsgemäßen Zustands.","answer":"Maßnahmen zum Erhalt des bestimmungsgemäßen Zustands. Instandhaltung umfasst Maßnahmen, die den ordnungsgemäßen Zustand erhalten und Verschleiß vorbeugen. Sie ist von Modernisierung und größerer Instandsetzung zu unterscheiden.","url":"/lexikon/instandhaltung/","keywords":["instandhaltung","maßnahmen","zum","erhalt","bestimmungsgemäßen","zustands.","umfasst","ordnungsgemäßen","zustand","erhalten","verschleiß","vorbeugen.","sie","modernisierung","größerer","instandsetzung","unterscheiden."]},{"kind":"lexicon","id":"instandhaltungsstau","title":"Instandhaltungsstau","category":"Immobilienkauf","summary":"Aufgeschobener Erhaltungsbedarf.","answer":"Aufgeschobener Erhaltungsbedarf. Instandhaltungsstau bezeichnet aufgeschobene notwendige Erhaltungsmaßnahmen. Er ist ein wirtschaftliches Risiko, weil vermeintlich niedrige Kaufpreise durch kurzfristig erforderlichen CapEx neutralisiert werden können.","url":"/lexikon/instandhaltungsstau/","keywords":["instandhaltungsstau","aufgeschobener","erhaltungsbedarf.","bezeichnet","aufgeschobene","notwendige","erhaltungsmaßnahmen.","wirtschaftliches","risiko","weil","vermeintlich","niedrige","kaufpreise","durch","kurzfristig","erforderlichen","capex","neutralisiert","können."]},{"kind":"lexicon","id":"instandsetzung","title":"Instandsetzung","category":"Immobilienkauf","summary":"Wiederherstellung eines ordnungsgemäßen Zustands.","answer":"Wiederherstellung eines ordnungsgemäßen Zustands. Instandsetzung stellt einen bereits beeinträchtigten ordnungsgemäßen Zustand wieder her. Sie unterscheidet sich von vorbeugender Instandhaltung und von wert-/gebrauchserhöhender Modernisierung.","url":"/lexikon/instandsetzung/","keywords":["instandsetzung","wiederherstellung","eines","ordnungsgemäßen","zustands.","stellt","bereits","beeinträchtigten","zustand","wieder","her.","sie","unterscheidet","vorbeugender","instandhaltung","wert-/gebrauchserhöhender","modernisierung."]},{"kind":"lexicon","id":"irr","title":"IRR","category":"Kapitalanlage","summary":"Interner Zinsfuß eines Zahlungsstroms.","answer":"Interner Zinsfuß eines Zahlungsstroms. Die Internal Rate of Return ist der Diskontsatz, bei dem der Kapitalwert aller Ein- und Auszahlungen null wird. Sie berücksichtigt das Timing der Zahlungsströme und ist stark von Haltedauer und Exitannahme abhängig.","url":"/lexikon/irr/","keywords":["irr","interner","zinsfuß","eines","zahlungsstroms.","internal","rate","return","diskontsatz","kapitalwert","aller","ein-","auszahlungen","null","wird.","sie","berücksichtigt","timing","zahlungsströme","stark","haltedauer","exitannahme","abhängig."]},{"kind":"lexicon","id":"jahresnettokaltmiete","title":"Jahresnettokaltmiete","category":"Vermietung","summary":"Summe der Nettokaltmieten eines Jahres.","answer":"Summe der Nettokaltmieten eines Jahres. Jahresnettokaltmiete (JNKM) ist die Summe der vertraglichen Nettokaltmieten eines Jahres ohne umlagefähige Betriebskosten. Sie ist zentrale Basis für Faktor- und Bruttorenditerechnungen.","url":"/lexikon/jahresnettokaltmiete/","keywords":["jahresnettokaltmiete","summe","nettokaltmieten","eines","jahres.","jnkm","vertraglichen","jahres","ohne","umlagefähige","betriebskosten.","sie","zentrale","basis","faktor-","bruttorenditerechnungen."]},{"kind":"lexicon","id":"kapitaldienst","title":"Kapitaldienst","category":"Finanzierung","summary":"Zins und Tilgung eines Darlehens.","answer":"Zins und Tilgung eines Darlehens. Kapitaldienst ist die Summe aus Zins- und Tilgungszahlungen eines Darlehens in einer Periode. Er bestimmt die laufende Liquiditätsbelastung und ist zentral für DSCR und Tragfähigkeitsrechnungen.","url":"/lexikon/kapitaldienst/","keywords":["kapitaldienst","zins","tilgung","eines","darlehens.","summe","aus","zins-","tilgungszahlungen","darlehens","periode.","bestimmt","laufende","liquiditätsbelastung","zentral","dscr","tragfähigkeitsrechnungen."]},{"kind":"lexicon","id":"kapitalisierungszins","title":"Kapitalisierungszins","category":"Finanzierung","summary":"Zinssatz zur Umrechnung künftiger Erträge in einen heutigen Wert.","answer":"Zinssatz zur Umrechnung künftiger Erträge in einen heutigen Wert. Kapitalisierungszins ist der Zinssatz, mit dem zukünftige Erträge in einen Barwert überführt werden. Je höher der Zinssatz bei gleichen Erträgen, desto niedriger der Barwert.","url":"/lexikon/kapitalisierungszins/","keywords":["kapitalisierungszins","zinssatz","zur","umrechnung","künftiger","erträge","heutigen","wert.","zukünftige","barwert","überführt","werden.","höher","gleichen","erträgen","desto","niedriger","barwert."]},{"kind":"lexicon","id":"kapitalwert","title":"Kapitalwert","category":"Kapitalanlage","summary":"Barwert aller Ein- und Auszahlungen abzüglich Anfangsinvestition.","answer":"Barwert aller Ein- und Auszahlungen abzüglich Anfangsinvestition. Der Kapitalwert ist die Summe der auf heute diskontierten zukünftigen Nettozahlungen abzüglich Anfangsinvestition. Positiv bedeutet: Die modellierten Zahlungsströme übertreffen die verwendete Renditeanforderung.","url":"/lexikon/kapitalwert/","keywords":["kapitalwert","barwert","aller","ein-","auszahlungen","abzüglich","anfangsinvestition.","summe","heute","diskontierten","zukünftigen","nettozahlungen","positiv","bedeutet","modellierten","zahlungsströme","übertreffen","verwendete","renditeanforderung."]},{"kind":"lexicon","id":"kappungsgrenze","title":"Kappungsgrenze","category":"Immobilienkauf","summary":"Grenze für Mieterhöhungen innerhalb eines Zeitraums.","answer":"Grenze für Mieterhöhungen innerhalb eines Zeitraums. Die Kappungsgrenze begrenzt bei Mieterhöhungen nach § 558 BGB die Erhöhung innerhalb von drei Jahren zusätzlich zur ortsüblichen Vergleichsmiete. In bestimmten Gebieten kann die Grenze abgesenkt sein.","url":"/lexikon/kappungsgrenze/","keywords":["kappungsgrenze","grenze","mieterhöhungen","innerhalb","eines","zeitraums.","begrenzt","nach","558","bgb","erhöhung","drei","jahren","zusätzlich","zur","ortsüblichen","vergleichsmiete.","bestimmten","gebieten","kann","abgesenkt","sein."]},{"kind":"lexicon","id":"kaufnebenkosten","title":"Kaufnebenkosten","category":"Immobilienkauf","summary":"Zusätzliche Erwerbskosten neben dem Kaufpreis.","answer":"Zusätzliche Erwerbskosten neben dem Kaufpreis. Kaufnebenkosten umfassen insbesondere Grunderwerbsteuer, Notar/Grundbuch und gegebenenfalls Maklercourtage. Zusätzlich können Finanzierung, Gutachten, Renovierung oder Möblierung den tatsächlichen Kapitalbedarf erhöhen.","url":"/lexikon/kaufnebenkosten/","keywords":["kaufnebenkosten","zusätzliche","erwerbskosten","neben","kaufpreis.","umfassen","insbesondere","grunderwerbsteuer","notar/grundbuch","gegebenenfalls","maklercourtage.","zusätzlich","können","finanzierung","gutachten","renovierung","möblierung","tatsächlichen","kapitalbedarf","erhöhen."]},{"kind":"lexicon","id":"kaufpreisfaktor","title":"Kaufpreisfaktor","category":"Kapitalanlage","summary":"Kaufpreis geteilt durch Jahresnettokaltmiete.","answer":"Kaufpreis geteilt durch Jahresnettokaltmiete. Der Kaufpreisfaktor setzt Kaufpreis und Jahresnettokaltmiete ins Verhältnis. Er ist bei identischer Basis der Kehrwert der Bruttomietrendite und ignoriert Nebenkosten, Bewirtschaftung, Finanzierung und CapEx.","url":"/lexikon/kaufpreisfaktor/","keywords":["kaufpreisfaktor","kaufpreis","geteilt","durch","jahresnettokaltmiete.","setzt","jahresnettokaltmiete","ins","verhältnis.","identischer","basis","kehrwert","bruttomietrendite","ignoriert","nebenkosten","bewirtschaftung","finanzierung","capex."]},{"kind":"lexicon","id":"kreditwurdigkeitsprufung","title":"Kreditwürdigkeitsprüfung","category":"Immobilienkauf","summary":"Prüfung von Einkommen, Vermögen, Verpflichtungen und Zahlungsverhalten.","answer":"Prüfung von Einkommen, Vermögen, Verpflichtungen und Zahlungsverhalten. Die Kreditwürdigkeitsprüfung beurteilt, ob der Kreditnehmer die Verpflichtungen aus dem Darlehen voraussichtlich erfüllen kann. Bei Immobiliardarlehen werden persönliche Tragfähigkeit und Objekt-/Sicherheitenbewertung zusammengeführt.","url":"/lexikon/kreditwurdigkeitsprufung/","keywords":["kreditwürdigkeitsprüfung","prüfung","einkommen","vermögen","verpflichtungen","zahlungsverhalten.","beurteilt","kreditnehmer","aus","darlehen","voraussichtlich","erfüllen","kann.","immobiliardarlehen","persönliche","tragfähigkeit","objekt-/sicherheitenbewertung","zusammengeführt."]},{"kind":"lexicon","id":"leerstand","title":"Leerstand","category":"Vermietung","summary":"Nicht vermietete Fläche oder Einheit.","answer":"Nicht vermietete Fläche oder Einheit. Leerstand ist der Zeitraum oder Anteil ohne zahlenden Nutzer. Wirtschaftlich muss zwischen kurzfristigem Vermietungsleerstand, strategischem Leerstand und strukturellem Leerstand unterschieden werden.","url":"/lexikon/leerstand/","keywords":["leerstand","vermietete","fläche","einheit.","zeitraum","anteil","ohne","zahlenden","nutzer.","wirtschaftlich","muss","zwischen","kurzfristigem","vermietungsleerstand","strategischem","strukturellem","unterschieden","werden."]},{"kind":"lexicon","id":"liegenschaftszins","title":"Liegenschaftszins","category":"Finanzierung","summary":"Marktüblicher Zinssatz im Ertragswertverfahren.","answer":"Marktüblicher Zinssatz im Ertragswertverfahren. Der Liegenschaftszins ist ein marktbezogener Zinssatz in der Immobilienwertermittlung, der die marktübliche Verzinsung von Grundstücken bestimmter Art abbildet. Er ist keine Bankkondition und kein individueller Renditewunsch.","url":"/lexikon/liegenschaftszins/","keywords":["liegenschaftszins","marktüblicher","zinssatz","ertragswertverfahren.","marktbezogener","immobilienwertermittlung","marktübliche","verzinsung","grundstücken","bestimmter","art","abbildet.","keine","bankkondition","kein","individueller","renditewunsch."]},{"kind":"lexicon","id":"liquiditatsreserve","title":"Liquiditätsreserve","category":"Immobilienkauf","summary":"Sofort verfügbare Mittel für Unvorhergesehenes.","answer":"Sofort verfügbare Mittel für Unvorhergesehenes. Liquiditätsreserve ist frei verfügbares Kapital für ungeplante Ausgaben, Leerstand, Reparaturen oder Finanzierungslücken. Sie sollte nicht mit langfristig gebundenem Eigenkapital oder WEG-Rücklagen verwechselt werden.","url":"/lexikon/liquiditatsreserve/","keywords":["liquiditätsreserve","sofort","verfügbare","mittel","unvorhergesehenes.","frei","verfügbares","kapital","ungeplante","ausgaben","leerstand","reparaturen","finanzierungslücken.","sie","sollte","langfristig","gebundenem","eigenkapital","weg-rücklagen","verwechselt","werden."]},{"kind":"lexicon","id":"ltv","title":"LTV","category":"Finanzierung","summary":"Loan-to-Value: Darlehen im Verhältnis zu einem Objektwert.","answer":"Loan-to-Value: Darlehen im Verhältnis zu einem Objektwert. Loan-to-Value bezeichnet das Verhältnis von Darlehen zu einem definierten Objektwert. Im deutschen Bankgeschäft ist davon der Beleihungsauslauf auf Basis des Beleihungswerts zu unterscheiden. Für internationale Vergleiche muss immer geklärt werden, welcher Wert im Nenner steht.","url":"/lexikon/ltv/","keywords":["ltv","loan-to-value","darlehen","verhältnis","objektwert.","bezeichnet","definierten","deutschen","bankgeschäft","davon","beleihungsauslauf","basis","beleihungswerts","unterscheiden.","internationale","vergleiche","muss","immer","geklärt","welcher","wert","nenner","steht."]},{"kind":"lexicon","id":"maklerprovision","title":"Maklerprovision","category":"Immobilienkauf","summary":"Vergütung für die Vermittlungs- oder Nachweistätigkeit.","answer":"Vergütung für die Vermittlungs- oder Nachweistätigkeit. Maklerprovision ist die vertraglich vereinbarte Vergütung für den erfolgreichen Nachweis oder die Vermittlung. Für Verbraucher beim Kauf einer Wohnung oder eines Einfamilienhauses gelten besondere Regeln zur Verteilung der Maklerkosten; für andere Immobilienarten ist die konkrete Provisionsvereinbarung maßgeblich.","url":"/lexikon/maklerprovision/","keywords":["maklerprovision","vergütung","vermittlungs-","nachweistätigkeit.","vertraglich","vereinbarte","erfolgreichen","nachweis","vermittlung.","verbraucher","beim","kauf","wohnung","eines","einfamilienhauses","gelten","besondere","regeln","zur","verteilung","maklerkosten","andere","immobilienarten","konkrete","provisionsvereinbarung","maßgeblich."]},{"kind":"lexicon","id":"mietausfall","title":"Mietausfall","category":"Immobilienkauf","summary":"Ausbleibender Mietertrag durch Leerstand oder Nichtzahlung.","answer":"Ausbleibender Mietertrag durch Leerstand oder Nichtzahlung. Mietausfall ist tatsächlich nicht vereinnahmte Sollmiete durch Leerstand, Zahlungsstörung oder Forderungsausfall. Er sollte bei Einzelobjekten möglichst aus konkretem Mieterrisiko und Vermietbarkeit statt nur pauschal geschätzt werden.","url":"/lexikon/mietausfall/","keywords":["mietausfall","ausbleibender","mietertrag","durch","leerstand","nichtzahlung.","tatsächlich","vereinnahmte","sollmiete","zahlungsstörung","forderungsausfall.","sollte","einzelobjekten","möglichst","aus","konkretem","mieterrisiko","vermietbarkeit","statt","pauschal","geschätzt","werden."]},{"kind":"lexicon","id":"mietbindung","title":"Mietbindung","category":"Immobilienkauf","summary":"Rechtliche Bindung von Miethöhe oder Belegung.","answer":"Rechtliche Bindung von Miethöhe oder Belegung. Mietbindung bezeichnet rechtliche Bindungen, die Miethöhe, Belegung oder Nutzung einschränken können, etwa im geförderten Wohnungsbau. Sie beeinflusst Ertrag und Verwertungsmöglichkeiten.","url":"/lexikon/mietbindung/","keywords":["mietbindung","rechtliche","bindung","miethöhe","belegung.","bezeichnet","bindungen","belegung","nutzung","einschränken","können","etwa","geförderten","wohnungsbau.","sie","beeinflusst","ertrag","verwertungsmöglichkeiten."]},{"kind":"lexicon","id":"mietpreisbremse","title":"Mietpreisbremse","category":"Immobilienkauf","summary":"Gesetzliche Begrenzung der Wiedervermietungsmiete in bestimmten Gebieten.","answer":"Gesetzliche Begrenzung der Wiedervermietungsmiete in bestimmten Gebieten. Die Mietpreisbremse begrenzt in ausgewiesenen Gebieten die zulässige Neuvertragsmiete grundsätzlich nach §§ 556d ff. BGB, vorbehaltlich gesetzlicher Ausnahmen und Vormietenregeln. Sie ist von der Kappungsgrenze im laufenden Mietverhältnis zu unterscheiden.","url":"/lexikon/mietpreisbremse/","keywords":["mietpreisbremse","gesetzliche","begrenzung","wiedervermietungsmiete","bestimmten","gebieten.","begrenzt","ausgewiesenen","gebieten","zulässige","neuvertragsmiete","grundsätzlich","nach","556d","ff.","bgb","vorbehaltlich","gesetzlicher","ausnahmen","vormietenregeln.","sie","kappungsgrenze","laufenden","mietverhältnis","unterscheiden."]},{"kind":"lexicon","id":"mietrendite","title":"Mietrendite","category":"Kapitalanlage","summary":"Mietertrag im Verhältnis zu einer Wert- oder Kostenbasis.","answer":"Mietertrag im Verhältnis zu einer Wert- oder Kostenbasis. Mietertrag im Verhältnis zu einer Wert- oder Kostenbasis. Mietrendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/mietrendite/","keywords":["mietrendite","mietertrag","verhältnis","wert-","kostenbasis.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"mietspiegel","title":"Mietspiegel","category":"Immobilienkauf","summary":"Übersicht ortsüblicher Vergleichsmieten.","answer":"Übersicht ortsüblicher Vergleichsmieten. Mietspiegel geben die ortsübliche Vergleichsmiete nach gesetzlichen Kriterien wieder. Sie dienen insbesondere als Begründungsmittel für Mieterhöhungen und sind von Portal-Angebotsmieten zu unterscheiden.","url":"/lexikon/mietspiegel/","keywords":["mietspiegel","übersicht","ortsüblicher","vergleichsmieten.","geben","ortsübliche","vergleichsmiete","nach","gesetzlichen","kriterien","wieder.","sie","dienen","insbesondere","begründungsmittel","mieterhöhungen","portal-angebotsmieten","unterscheiden."]},{"kind":"lexicon","id":"mietuberschuss","title":"Mietüberschuss","category":"Immobilienkauf","summary":"Miete abzüglich objektspezifischer laufender Kosten.","answer":"Miete abzüglich objektspezifischer laufender Kosten. Mietüberschuss ist der nach definierten laufenden Objektkosten verbleibende Mietertrag. Ob Finanzierung, Steuern oder Rücklagen enthalten sind, muss ausdrücklich definiert werden.","url":"/lexikon/mietuberschuss/","keywords":["mietüberschuss","miete","abzüglich","objektspezifischer","laufender","kosten.","nach","definierten","laufenden","objektkosten","verbleibende","mietertrag.","finanzierung","steuern","rücklagen","enthalten","muss","ausdrücklich","definiert","werden."]},{"kind":"lexicon","id":"miteigentumsanteil","title":"Miteigentumsanteil","category":"Immobilienkauf","summary":"Rechnerischer Anteil am Gemeinschaftseigentum.","answer":"Rechnerischer Anteil am Gemeinschaftseigentum. Der Miteigentumsanteil beschreibt den Bruchteil, mit dem ein Wohnungseigentümer am Gemeinschaftseigentum beteiligt ist. Er kann für Kosten- und Stimmrechtsfragen relevant sein, soweit Gemeinschaftsordnung oder Gesetz nichts anderes regeln.","url":"/lexikon/miteigentumsanteil/","keywords":["miteigentumsanteil","rechnerischer","anteil","gemeinschaftseigentum.","beschreibt","bruchteil","wohnungseigentümer","gemeinschaftseigentum","beteiligt","ist.","kann","kosten-","stimmrechtsfragen","relevant","sein","soweit","gemeinschaftsordnung","gesetz","nichts","anderes","regeln."]},{"kind":"lexicon","id":"modernisierung","title":"Modernisierung","category":"Immobilienkauf","summary":"Bauliche Verbesserung über reine Erhaltung hinaus.","answer":"Bauliche Verbesserung über reine Erhaltung hinaus. Modernisierung verbessert den Gebrauchswert, spart nachhaltig Energie/Wasser oder schafft neuen Wohnraum beziehungsweise erfüllt weitere gesetzliche Tatbestände. Sie ist von bloßer Erhaltung/Instandsetzung abzugrenzen, weil dies mietrechtlich und wirtschaftlich unterschiedliche Folgen hat.","url":"/lexikon/modernisierung/","keywords":["modernisierung","bauliche","verbesserung","über","reine","erhaltung","hinaus.","verbessert","gebrauchswert","spart","nachhaltig","energie/wasser","schafft","neuen","wohnraum","beziehungsweise","erfüllt","weitere","gesetzliche","tatbestände.","sie","bloßer","erhaltung/instandsetzung","abzugrenzen","weil","dies","mietrechtlich","wirtschaftlich","unterschiedliche","folgen","hat."]},{"kind":"lexicon","id":"nachrangdarlehen","title":"Nachrangdarlehen","category":"Finanzierung","summary":"Darlehen, dessen Gläubiger im Rang hinter andere Gläubiger tritt.","answer":"Darlehen, dessen Gläubiger im Rang hinter andere Gläubiger tritt. Ein Nachrangdarlehen wird im Rang hinter vorrangigen Gläubigern bedient beziehungsweise besichert. Wegen des höheren Verlustrisikos ist es häufig teurer und wird von Banken bei der Gesamtfinanzierung gesondert bewertet.","url":"/lexikon/nachrangdarlehen/","keywords":["nachrangdarlehen","darlehen","dessen","gläubiger","rang","hinter","andere","tritt.","vorrangigen","gläubigern","bedient","beziehungsweise","besichert.","wegen","höheren","verlustrisikos","häufig","teurer","banken","gesamtfinanzierung","gesondert","bewertet."]},{"kind":"lexicon","id":"nebenkostenabrechnung","title":"Nebenkostenabrechnung","category":"Immobilienkauf","summary":"Abrechnung umlagefähiger Betriebskosten gegenüber Mietern.","answer":"Abrechnung umlagefähiger Betriebskosten gegenüber Mietern. Die Nebenkostenabrechnung verteilt tatsächlich entstandene umlagefähige Betriebskosten auf den Mieter nach dem vereinbarten Schlüssel und rechnet Vorauszahlungen an. Formelle und materielle Fehler können Nachforderungen gefährden.","url":"/lexikon/nebenkostenabrechnung/","keywords":["nebenkostenabrechnung","abrechnung","umlagefähiger","betriebskosten","gegenüber","mietern.","verteilt","tatsächlich","entstandene","umlagefähige","mieter","nach","vereinbarten","schlüssel","rechnet","vorauszahlungen","an.","formelle","materielle","fehler","können","nachforderungen","gefährden."]},{"kind":"lexicon","id":"nettomietrendite","title":"Nettomietrendite","category":"Kapitalanlage","summary":"Jahresmiete abzüglich definierter Eigentümerkosten im Verhältnis zum Kaufpreis.","answer":"Jahresmiete abzüglich definierter Eigentümerkosten im Verhältnis zum Kaufpreis. Die Nettomietrendite berücksichtigt im Gegensatz zur Bruttomietrendite laufende Eigentümerkosten und sollte auf eine klar definierte Investitionsbasis bezogen werden. Unterschiedliche Marktquellen verwenden teils abweichende Definitionen.","url":"/lexikon/nettomietrendite/","keywords":["nettomietrendite","jahresmiete","abzüglich","definierter","eigentümerkosten","verhältnis","zum","kaufpreis.","berücksichtigt","gegensatz","zur","bruttomietrendite","laufende","sollte","klar","definierte","investitionsbasis","bezogen","werden.","unterschiedliche","marktquellen","verwenden","teils","abweichende","definitionen."]},{"kind":"lexicon","id":"nettovermogen","title":"Nettovermögen","category":"Immobilienkauf","summary":"Vermögenswert abzüglich Verbindlichkeiten; Definition im Modell beachten.","answer":"Vermögenswert abzüglich Verbindlichkeiten; Definition im Modell beachten. Nettovermögen ist Vermögen abzüglich sämtlicher Verbindlichkeiten. Bei Immobilienvermögen ist deshalb nicht der Marktwert allein entscheidend, sondern Marktwert minus offene Darlehen und sonstige Schulden.","url":"/lexikon/nettovermogen/","keywords":["nettovermögen","vermögenswert","abzüglich","verbindlichkeiten","definition","modell","beachten.","vermögen","sämtlicher","verbindlichkeiten.","immobilienvermögen","deshalb","marktwert","allein","entscheidend","sondern","minus","offene","darlehen","sonstige","schulden."]},{"kind":"lexicon","id":"niebrauch","title":"Nießbrauch","category":"Immobilienkauf","summary":"Umfassendes Nutzungsrecht an einer Sache.","answer":"Umfassendes Nutzungsrecht an einer Sache. Nießbrauch gewährt dem Berechtigten typischerweise das Recht, die Nutzungen einer Sache zu ziehen, etwa selbst zu wohnen oder Mieten zu vereinnahmen. Ein eingetragener Nießbrauch kann Verkehrswert, Finanzierbarkeit und Verfügbarkeit für den Käufer stark beeinflussen.","url":"/lexikon/niebrauch/","keywords":["nießbrauch","umfassendes","nutzungsrecht","sache.","gewährt","berechtigten","typischerweise","recht","nutzungen","sache","ziehen","etwa","selbst","wohnen","mieten","vereinnahmen.","eingetragener","kann","verkehrswert","finanzierbarkeit","verfügbarkeit","käufer","stark","beeinflussen."]},{"kind":"lexicon","id":"nominalrendite","title":"Nominalrendite","category":"Kapitalanlage","summary":"Rendite ohne Bereinigung um Inflation.","answer":"Rendite ohne Bereinigung um Inflation. Rendite ohne Bereinigung um Inflation. Nominalrendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/nominalrendite/","keywords":["nominalrendite","rendite","ohne","bereinigung","inflation.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"nominalzins","title":"Nominalzins","category":"Finanzierung","summary":"Vertraglicher Zinssatz ohne weitere Kosten.","answer":"Vertraglicher Zinssatz ohne weitere Kosten. Nominalzins bezeichnet den vereinbarten Zinssatz ohne vollständige Einbeziehung sämtlicher preisbestimmender Kosten. Bei Verbraucherdarlehen ist für Angebotsvergleiche deshalb zusätzlich der effektive Jahreszins relevant.","url":"/lexikon/nominalzins/","keywords":["nominalzins","vertraglicher","zinssatz","ohne","weitere","kosten.","bezeichnet","vereinbarten","vollständige","einbeziehung","sämtlicher","preisbestimmender","verbraucherdarlehen","angebotsvergleiche","deshalb","zusätzlich","effektive","jahreszins","relevant."]},{"kind":"lexicon","id":"objektrendite","title":"Objektrendite","category":"Kapitalanlage","summary":"Rendite des Objekts vor individueller Finanzierung.","answer":"Rendite des Objekts vor individueller Finanzierung. Rendite des Objekts vor individueller Finanzierung. Objektrendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/objektrendite/","keywords":["objektrendite","rendite","objekts","vor","individueller","finanzierung.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"operating-expenses","title":"Operating Expenses","category":"Immobilienkauf","summary":"Laufende Bewirtschaftungskosten.","answer":"Laufende Bewirtschaftungskosten. Operating Expenses (OpEx) sind laufende betriebliche Objektkosten. Welche Positionen enthalten sind, muss im jeweiligen Modell definiert werden; CapEx und Finanzierung werden regelmäßig getrennt betrachtet.","url":"/lexikon/operating-expenses/","keywords":["operating","expenses","laufende","bewirtschaftungskosten.","opex","betriebliche","objektkosten.","welche","positionen","enthalten","muss","jeweiligen","modell","definiert","capex","finanzierung","regelmäßig","getrennt","betrachtet."]},{"kind":"lexicon","id":"opportunitatskosten","title":"Opportunitätskosten","category":"Immobilienkauf","summary":"Entgangener Nutzen der besten nicht gewählten Alternative.","answer":"Entgangener Nutzen der besten nicht gewählten Alternative. Opportunitätskosten sind der entgangene Nutzen der besten nicht gewählten Alternative. Beim Eigenkapitaleinsatz zeigen sie, was gebundenes Kapital andernorts hätte erwirtschaften oder an Sicherheit bieten können.","url":"/lexikon/opportunitatskosten/","keywords":["opportunitätskosten","entgangener","nutzen","besten","gewählten","alternative.","entgangene","beim","eigenkapitaleinsatz","zeigen","sie","gebundenes","kapital","andernorts","hätte","erwirtschaften","sicherheit","bieten","können."]},{"kind":"lexicon","id":"portfolio","title":"Portfolio","category":"Kapitalanlage","summary":"Gesamtheit mehrerer Investments.","answer":"Gesamtheit mehrerer Investments. Gesamtheit mehrerer Investments. Portfolio ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/portfolio/","keywords":["portfolio","gesamtheit","mehrerer","investments.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"preis-miet-verhaltnis","title":"Preis-Miet-Verhältnis","category":"Immobilienkauf","summary":"Kaufpreis relativ zum laufenden Mietniveau.","answer":"Kaufpreis relativ zum laufenden Mietniveau. Das Preis-Miet-Verhältnis beschreibt, wie hoch der Kaufpreis im Verhältnis zur Jahresmiete ist und entspricht bei gleicher Basis dem Kaufpreisfaktor. Es sagt nichts über Kosten, Finanzierung oder Zustand aus.","url":"/lexikon/preis-miet-verhaltnis/","keywords":["preis-miet-verhältnis","kaufpreis","relativ","zum","laufenden","mietniveau.","beschreibt","hoch","verhältnis","zur","jahresmiete","entspricht","gleicher","basis","kaufpreisfaktor.","sagt","nichts","über","kosten","finanzierung","zustand","aus."]},{"kind":"lexicon","id":"prolongation","title":"Prolongation","category":"Finanzierung","summary":"Verlängerung einer Finanzierung beim bisherigen Kreditgeber.","answer":"Verlängerung einer Finanzierung beim bisherigen Kreditgeber. Prolongation ist die Verlängerung beziehungsweise Anschlussvereinbarung eines bestehenden Darlehens bei derselben Bank, meist für die Restschuld nach Zinsbindungsende.","url":"/lexikon/prolongation/","keywords":["prolongation","verlängerung","finanzierung","beim","bisherigen","kreditgeber.","beziehungsweise","anschlussvereinbarung","eines","bestehenden","darlehens","derselben","bank","meist","restschuld","nach","zinsbindungsende."]},{"kind":"lexicon","id":"reale-rendite","title":"Reale Rendite","category":"Kapitalanlage","summary":"Rendite nach Berücksichtigung der Inflation.","answer":"Rendite nach Berücksichtigung der Inflation. Rendite nach Berücksichtigung der Inflation. Reale Rendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/reale-rendite/","keywords":["reale","rendite","nach","berücksichtigung","inflation.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"restnutzungsdauer","title":"Restnutzungsdauer","category":"Immobilienkauf","summary":"Voraussichtliche verbleibende wirtschaftliche Nutzungsdauer.","answer":"Voraussichtliche verbleibende wirtschaftliche Nutzungsdauer. Die Restnutzungsdauer beschreibt den Zeitraum, in dem ein Gebäude voraussichtlich noch wirtschaftlich nutzbar ist. Sie ist in Bewertung und gegebenenfalls beim steuerlichen Nachweis einer kürzeren tatsächlichen Nutzungsdauer relevant.","url":"/lexikon/restnutzungsdauer/","keywords":["restnutzungsdauer","voraussichtliche","verbleibende","wirtschaftliche","nutzungsdauer.","beschreibt","zeitraum","gebäude","voraussichtlich","noch","wirtschaftlich","nutzbar","ist.","sie","bewertung","gegebenenfalls","beim","steuerlichen","nachweis","kürzeren","tatsächlichen","nutzungsdauer","relevant."]},{"kind":"lexicon","id":"restschuld","title":"Restschuld","category":"Immobilienkauf","summary":"Noch nicht zurückgezahlter Darlehensbetrag.","answer":"Noch nicht zurückgezahlter Darlehensbetrag. Restschuld ist der nach geleisteten Tilgungen noch offene Darlehensbetrag. Sie bestimmt am Ende der Zinsbindung den Finanzierungsbedarf für die Anschlussfinanzierung.","url":"/lexikon/restschuld/","keywords":["restschuld","noch","zurückgezahlter","darlehensbetrag.","nach","geleisteten","tilgungen","offene","sie","bestimmt","ende","zinsbindung","finanzierungsbedarf","anschlussfinanzierung."]},{"kind":"lexicon","id":"risikopuffer","title":"Risikopuffer","category":"Immobilienkauf","summary":"Konservativer Abschlag oder Zuschlag zur Abdeckung von Unsicherheit.","answer":"Konservativer Abschlag oder Zuschlag zur Abdeckung von Unsicherheit. Risikopuffer ist eine bewusst konservative Reserve in Geld oder Annahmen, um Unsicherheit abzudecken. Er sollte transparent ausgewiesen statt in mehreren versteckten Abschlägen doppelt berücksichtigt werden.","url":"/lexikon/risikopuffer/","keywords":["risikopuffer","konservativer","abschlag","zuschlag","zur","abdeckung","unsicherheit.","bewusst","konservative","reserve","geld","annahmen","unsicherheit","abzudecken.","sollte","transparent","ausgewiesen","statt","mehreren","versteckten","abschlägen","doppelt","berücksichtigt","werden."]},{"kind":"lexicon","id":"rucklage","title":"Rücklage","category":"Vermietung","summary":"Für künftige Ausgaben reservierte Mittel.","answer":"Für künftige Ausgaben reservierte Mittel. Rücklage ist ein zurückgehaltener Kapitalbetrag für zukünftige Ausgaben oder Risiken. Bei Immobilien muss zwischen privater Liquiditätsreserve und WEG-Erhaltungsrücklage unterschieden werden.","url":"/lexikon/rucklage/","keywords":["rücklage","künftige","ausgaben","reservierte","mittel.","zurückgehaltener","kapitalbetrag","zukünftige","risiken.","immobilien","muss","zwischen","privater","liquiditätsreserve","weg-erhaltungsrücklage","unterschieden","werden."]},{"kind":"lexicon","id":"sachwert","title":"Sachwert","category":"Immobilienkauf","summary":"Aus Herstellungskosten und Bodenwert abgeleiteter Wert.","answer":"Aus Herstellungskosten und Bodenwert abgeleiteter Wert. Sachwert ist ein im Sachwertverfahren abgeleiteter Immobilienwert aus Bodenwert und wertmäßigem Gebäude-/Anlagenbestand unter Marktanpassung. Er ist besonders bei eigennutzungsgeprägten Objekten relevant.","url":"/lexikon/sachwert/","keywords":["sachwert","aus","herstellungskosten","bodenwert","abgeleiteter","wert.","sachwertverfahren","immobilienwert","wertmäßigem","gebäude-/anlagenbestand","unter","marktanpassung.","besonders","eigennutzungsgeprägten","objekten","relevant."]},{"kind":"lexicon","id":"sondereigentum","title":"Sondereigentum","category":"Immobilienkauf","summary":"Alleineigentum an bestimmten Räumen einer WEG.","answer":"Alleineigentum an bestimmten Räumen einer WEG. Sondereigentum ist das dem einzelnen Wohnungseigentümer allein zugeordnete Eigentum an bestimmten Räumen und Bestandteilen. Tragende Teile und viele gemeinschaftlich dienende Bauteile bleiben Gemeinschaftseigentum.","url":"/lexikon/sondereigentum/","keywords":["sondereigentum","alleineigentum","bestimmten","räumen","weg.","einzelnen","wohnungseigentümer","allein","zugeordnete","eigentum","bestandteilen.","tragende","teile","viele","gemeinschaftlich","dienende","bauteile","bleiben","gemeinschaftseigentum."]},{"kind":"lexicon","id":"sondertilgung","title":"Sondertilgung","category":"Finanzierung","summary":"Zusätzliche Tilgung außerhalb der regulären Rate.","answer":"Zusätzliche Tilgung außerhalb der regulären Rate. Sondertilgung ist eine zusätzliche außerplanmäßige Tilgung außerhalb der regulären Rate, soweit der Darlehensvertrag dies erlaubt. Sie reduziert Restschuld und zukünftige Zinsbelastung, bindet aber Liquidität.","url":"/lexikon/sondertilgung/","keywords":["sondertilgung","zusätzliche","tilgung","außerhalb","regulären","rate.","außerplanmäßige","rate","soweit","darlehensvertrag","dies","erlaubt.","sie","reduziert","restschuld","zukünftige","zinsbelastung","bindet","aber","liquidität."]},{"kind":"lexicon","id":"sonderumlage","title":"Sonderumlage","category":"Vermietung","summary":"Zusätzliche Zahlung der Wohnungseigentümer aufgrund eines WEG-Beschlusses.","answer":"Zusätzliche Zahlung der Wohnungseigentümer aufgrund eines WEG-Beschlusses. Eine Sonderumlage ist ein zusätzlicher Finanzierungsbeitrag der Wohnungseigentümer, wenn laufende Mittel und Rücklage nicht ausreichen. Für Käufer sind sowohl bereits beschlossene Umlagen als auch aus Protokollen erkennbare größere Maßnahmen wirtschaftlich relevant.","url":"/lexikon/sonderumlage/","keywords":["sonderumlage","zusätzliche","zahlung","wohnungseigentümer","aufgrund","eines","weg-beschlusses.","zusätzlicher","finanzierungsbeitrag","wenn","laufende","mittel","rücklage","ausreichen.","käufer","sowohl","bereits","beschlossene","umlagen","aus","protokollen","erkennbare","größere","maßnahmen","wirtschaftlich","relevant."]},{"kind":"lexicon","id":"spekulationsfrist","title":"Spekulationsfrist","category":"Steuern","summary":"Umgangssprachliche Bezeichnung für steuerlich relevante Haltefristen.","answer":"Umgangssprachliche Bezeichnung für steuerlich relevante Haltefristen. Die sogenannte Spekulationsfrist bezeichnet im Privatvermögen die Zehnjahresfrist des § 23 EStG für private Grundstücksveräußerungsgeschäfte; für bestimmte Eigennutzungsfälle gelten Ausnahmen. Bei Betriebsvermögen oder gewerblichem Grundstückshandel greifen andere Regeln.","url":"/lexikon/spekulationsfrist/","keywords":["spekulationsfrist","umgangssprachliche","bezeichnung","steuerlich","relevante","haltefristen.","sogenannte","bezeichnet","privatvermögen","zehnjahresfrist","estg","private","grundstücksveräußerungsgeschäfte","bestimmte","eigennutzungsfälle","gelten","ausnahmen.","betriebsvermögen","gewerblichem","grundstückshandel","greifen","andere","regeln."]},{"kind":"lexicon","id":"staffelmiete","title":"Staffelmiete","category":"Vermietung","summary":"Miete mit im Voraus vereinbarten Erhöhungsbeträgen.","answer":"Miete mit im Voraus vereinbarten Erhöhungsbeträgen. Bei der Staffelmiete werden zukünftige Mietbeträge beziehungsweise Erhöhungen bereits im Vertrag als Geldbetrag festgelegt. Zwischen den Staffeln muss die Miete jeweils mindestens ein Jahr unverändert bleiben.","url":"/lexikon/staffelmiete/","keywords":["staffelmiete","miete","voraus","vereinbarten","erhöhungsbeträgen.","zukünftige","mietbeträge","beziehungsweise","erhöhungen","bereits","vertrag","geldbetrag","festgelegt.","zwischen","staffeln","muss","jeweils","mindestens","jahr","unverändert","bleiben."]},{"kind":"lexicon","id":"steuerlicher-uberschuss","title":"Steuerlicher Überschuss","category":"Steuern","summary":"Steuerlich ermittelte Einkünfte nach abzugsfähigen Aufwendungen.","answer":"Steuerlich ermittelte Einkünfte nach abzugsfähigen Aufwendungen. Der steuerliche Überschuss aus Vermietung ergibt sich vereinfacht aus steuerpflichtigen Einnahmen minus abzugsfähigen Werbungskosten. Er unterscheidet sich vom Cashflow, weil AfA und Tilgung unterschiedlich behandelt werden.","url":"/lexikon/steuerlicher-uberschuss/","keywords":["steuerlicher","überschuss","steuerlich","ermittelte","einkünfte","nach","abzugsfähigen","aufwendungen.","steuerliche","aus","vermietung","ergibt","vereinfacht","steuerpflichtigen","einnahmen","minus","werbungskosten.","unterscheidet","vom","cashflow","weil","afa","tilgung","unterschiedlich","behandelt","werden."]},{"kind":"lexicon","id":"stress-test","title":"Stress-Test","category":"Immobilienkauf","summary":"Berechnung unter ungünstigeren Annahmen.","answer":"Berechnung unter ungünstigeren Annahmen. Ein Stress-Test prüft die Tragfähigkeit unter bewusst verschlechterten Annahmen, etwa höherem Zins, Leerstand oder CapEx. Er unterscheidet sich von einer einfachen Sensitivität, weil mehrere Belastungen gleichzeitig kombiniert werden können.","url":"/lexikon/stress-test/","keywords":["stress-test","berechnung","unter","ungünstigeren","annahmen.","prüft","tragfähigkeit","bewusst","verschlechterten","annahmen","etwa","höherem","zins","leerstand","capex.","unterscheidet","einfachen","sensitivität","weil","mehrere","belastungen","gleichzeitig","kombiniert","können."]},{"kind":"lexicon","id":"teilungserklarung","title":"Teilungserklärung","category":"Immobilienkauf","summary":"Dokument zur Aufteilung eines Grundstücks in Wohnungs- oder Teileigentum.","answer":"Dokument zur Aufteilung eines Grundstücks in Wohnungs- oder Teileigentum. Die Teilungserklärung legt bei Wohnungseigentum die Aufteilung in Sonder- und Gemeinschaftseigentum sowie Miteigentumsanteile und häufig Nutzungs-/Kostenregelungen fest. Sie ist eine zentrale Rechtsgrundlage der ETW-Prüfung.","url":"/lexikon/teilungserklarung/","keywords":["teilungserklärung","dokument","zur","aufteilung","eines","grundstücks","wohnungs-","teileigentum.","legt","wohnungseigentum","sonder-","gemeinschaftseigentum","sowie","miteigentumsanteile","häufig","nutzungs-/kostenregelungen","fest.","sie","zentrale","rechtsgrundlage","etw-prüfung."]},{"kind":"lexicon","id":"tilgung","title":"Tilgung","category":"Finanzierung","summary":"Rückzahlung des Darlehenskapitals.","answer":"Rückzahlung des Darlehenskapitals. Tilgung ist die Rückzahlung des Darlehenskapitals. Im Annuitätendarlehen steigt der Tilgungsanteil innerhalb der konstanten Rate, weil der Zinsanteil mit sinkender Restschuld abnimmt.","url":"/lexikon/tilgung/","keywords":["tilgung","rückzahlung","darlehenskapitals.","annuitätendarlehen","steigt","tilgungsanteil","innerhalb","konstanten","rate","weil","zinsanteil","sinkender","restschuld","abnimmt."]},{"kind":"lexicon","id":"tilgungssatz","title":"Tilgungssatz","category":"Finanzierung","summary":"Anfänglicher oder laufender Anteil der Darlehensrückzahlung.","answer":"Anfänglicher oder laufender Anteil der Darlehensrückzahlung. Der Tilgungssatz beschreibt den anfänglichen jährlichen Kapitalrückzahlungsanteil bezogen auf die Darlehenssumme. Im Annuitätendarlehen steigt der tatsächliche Tilgungsanteil im Zeitverlauf.","url":"/lexikon/tilgungssatz/","keywords":["tilgungssatz","anfänglicher","laufender","anteil","darlehensrückzahlung.","beschreibt","anfänglichen","jährlichen","kapitalrückzahlungsanteil","bezogen","darlehenssumme.","annuitätendarlehen","steigt","tatsächliche","tilgungsanteil","zeitverlauf."]},{"kind":"lexicon","id":"total-return","title":"Total Return","category":"Kapitalanlage","summary":"Gesamtertrag aus laufenden Zahlungen und Wertveränderung.","answer":"Gesamtertrag aus laufenden Zahlungen und Wertveränderung. Gesamtertrag aus laufenden Zahlungen und Wertveränderung. Total Return ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/total-return/","keywords":["total","return","gesamtertrag","aus","laufenden","zahlungen","wertveränderung.","investmentkennzahl","bzw.","risikogröße.","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein."]},{"kind":"lexicon","id":"transaktionskosten","title":"Transaktionskosten","category":"Immobilienkauf","summary":"Kosten, die durch Erwerb oder Verkauf entstehen.","answer":"Kosten, die durch Erwerb oder Verkauf entstehen. Transaktionskosten sind Kosten für Erwerb, Finanzierung, Halten oder Verkauf, die zusätzlich zum reinen Vermögenswert entstehen. Sie beeinflussen besonders die Rendite kurzer Haltedauern.","url":"/lexikon/transaktionskosten/","keywords":["transaktionskosten","kosten","durch","erwerb","verkauf","entstehen.","finanzierung","halten","zusätzlich","zum","reinen","vermögenswert","sie","beeinflussen","besonders","rendite","kurzer","haltedauern."]},{"kind":"lexicon","id":"umlagefahige-kosten","title":"Umlagefähige Kosten","category":"Vermietung","summary":"Betriebskosten, die bei wirksamer Vereinbarung auf Mieter umgelegt werden können.","answer":"Betriebskosten, die bei wirksamer Vereinbarung auf Mieter umgelegt werden können. Umlagefähige Kosten sind Betriebskosten, die nach Gesetz und Mietvertrag auf den Mieter verteilt werden dürfen. Umlagefähigkeit bedeutet nicht, dass der Eigentümer kein Leerstands- oder Ausfallrisiko trägt.","url":"/lexikon/umlagefahige-kosten/","keywords":["umlagefähige","kosten","betriebskosten","wirksamer","vereinbarung","mieter","umgelegt","können.","nach","gesetz","mietvertrag","verteilt","dürfen.","umlagefähigkeit","bedeutet","eigentümer","kein","leerstands-","ausfallrisiko","trägt."]},{"kind":"lexicon","id":"umwandlung","title":"Umwandlung","category":"Immobilienkauf","summary":"Aufteilung eines Mietshauses in Wohnungseigentum.","answer":"Aufteilung eines Mietshauses in Wohnungseigentum. Umwandlung bezeichnet im Immobilienkontext häufig die Aufteilung eines Mietshauses in Wohnungseigentum. Sie kann genehmigungs-, miet- und milieuschutzrechtliche Besonderheiten auslösen.","url":"/lexikon/umwandlung/","keywords":["umwandlung","aufteilung","eines","mietshauses","wohnungseigentum.","bezeichnet","immobilienkontext","häufig","sie","kann","genehmigungs-","miet-","milieuschutzrechtliche","besonderheiten","auslösen."]},{"kind":"lexicon","id":"unterdeckung","title":"Unterdeckung","category":"Immobilienkauf","summary":"Situation, in der Erlös oder Wert die Verbindlichkeiten nicht deckt.","answer":"Situation, in der Erlös oder Wert die Verbindlichkeiten nicht deckt. Unterdeckung liegt vor, wenn vorhandene Mittel oder Erlöse eine Verpflichtung nicht vollständig decken. Bei Immobilien kann sie etwa entstehen, wenn Verkaufserlös nach Kosten unter der offenen Darlehensschuld liegt.","url":"/lexikon/unterdeckung/","keywords":["unterdeckung","situation","erlös","wert","verbindlichkeiten","deckt.","liegt","vor","wenn","vorhandene","mittel","erlöse","verpflichtung","vollständig","decken.","immobilien","kann","sie","etwa","entstehen","verkaufserlös","nach","kosten","unter","offenen","darlehensschuld","liegt."]},{"kind":"lexicon","id":"verkehrswert","title":"Verkehrswert","category":"Immobilienkauf","summary":"Marktwert nach den gesetzlichen Bewertungsgrundsätzen.","answer":"Marktwert nach den gesetzlichen Bewertungsgrundsätzen. Verkehrswert beziehungsweise Marktwert ist nach § 194 BauGB der Preis, der im gewöhnlichen Geschäftsverkehr unter Berücksichtigung der rechtlichen Gegebenheiten, tatsächlichen Eigenschaften und Lage ohne ungewöhnliche oder persönliche Verhältnisse erzielbar wäre.","url":"/lexikon/verkehrswert/","keywords":["verkehrswert","marktwert","nach","gesetzlichen","bewertungsgrundsätzen.","beziehungsweise","194","baugb","preis","gewöhnlichen","geschäftsverkehr","unter","berücksichtigung","rechtlichen","gegebenheiten","tatsächlichen","eigenschaften","lage","ohne","ungewöhnliche","persönliche","verhältnisse","erzielbar","wäre."]},{"kind":"lexicon","id":"vervielfaltiger","title":"Vervielfältiger","category":"Immobilienkauf","summary":"Synonym für Kaufpreisfaktor.","answer":"Synonym für Kaufpreisfaktor. Vervielfältiger wird im Immobilienmarkt häufig synonym für Kaufpreisfaktor verwendet; in Bewertungsverfahren kann „Vervielfältiger“ auch einen mathematischen Kapitalisierungsfaktor bezeichnen. Der Kontext muss deshalb klar sein.","url":"/lexikon/vervielfaltiger/","keywords":["vervielfältiger","synonym","kaufpreisfaktor.","immobilienmarkt","häufig","kaufpreisfaktor","verwendet","bewertungsverfahren","kann","mathematischen","kapitalisierungsfaktor","bezeichnen.","kontext","muss","deshalb","klar","sein."]},{"kind":"lexicon","id":"verwaltungskosten","title":"Verwaltungskosten","category":"Immobilienkauf","summary":"Kosten der kaufmännischen und technischen Verwaltung.","answer":"Kosten der kaufmännischen und technischen Verwaltung. Verwaltungskosten entstehen für kaufmännische und technische Verwaltung. Bei Wohnraummiete sind sie grundsätzlich nicht als Betriebskosten auf den Mieter umlagefähig und verbleiben daher in der Eigentümerrechnung.","url":"/lexikon/verwaltungskosten/","keywords":["verwaltungskosten","kosten","kaufmännischen","technischen","verwaltung.","entstehen","kaufmännische","technische","wohnraummiete","sie","grundsätzlich","betriebskosten","mieter","umlagefähig","verbleiben","daher","eigentümerrechnung."]},{"kind":"lexicon","id":"vollfinanzierung","title":"Vollfinanzierung","category":"Finanzierung","summary":"Finanzierung des Kaufpreises ohne Eigenkapitalanteil am Kaufpreis.","answer":"Finanzierung des Kaufpreises ohne Eigenkapitalanteil am Kaufpreis. Vollfinanzierung bedeutet regelmäßig, dass der Kaufpreis vollständig fremdfinanziert wird. Eine Finanzierung zusätzlich der Erwerbsnebenkosten wird häufig als 110-%-Finanzierung bezeichnet. Die höhere Fremdfinanzierung kann Zins und Unterdeckungsrisiko erhöhen.","url":"/lexikon/vollfinanzierung/","keywords":["vollfinanzierung","finanzierung","kaufpreises","ohne","eigenkapitalanteil","kaufpreis.","bedeutet","regelmäßig","kaufpreis","vollständig","fremdfinanziert","wird.","zusätzlich","erwerbsnebenkosten","häufig","110-%-finanzierung","bezeichnet.","höhere","fremdfinanzierung","kann","zins","unterdeckungsrisiko","erhöhen."]},{"kind":"lexicon","id":"vorfalligkeitsentschadigung","title":"Vorfälligkeitsentschädigung","category":"Immobilienkauf","summary":"Möglicher Ausgleich der Bank bei vorzeitiger Darlehensablösung.","answer":"Möglicher Ausgleich der Bank bei vorzeitiger Darlehensablösung. Eine Vorfälligkeitsentschädigung kann bei vorzeitiger Rückzahlung eines fest verzinsten Darlehens entstehen, wenn der Bank ein rechtlich ersatzfähiger Zinsschaden entsteht. Ob und in welcher Höhe sie anfällt, hängt vom Vertrag und gesetzlichen Kündigungs-/Berechnungsregeln ab.","url":"/lexikon/vorfalligkeitsentschadigung/","keywords":["vorfälligkeitsentschädigung","möglicher","ausgleich","bank","vorzeitiger","darlehensablösung.","kann","rückzahlung","eines","fest","verzinsten","darlehens","entstehen","wenn","rechtlich","ersatzfähiger","zinsschaden","entsteht.","welcher","höhe","sie","anfällt","hängt","vom","vertrag","gesetzlichen","kündigungs-/berechnungsregeln","ab."]},{"kind":"lexicon","id":"weg","title":"WEG","category":"Vermietung","summary":"Wohnungseigentümergemeinschaft.","answer":"Wohnungseigentümergemeinschaft. WEG bezeichnet je nach Kontext das Wohnungseigentumsgesetz oder die Gemeinschaft der Wohnungseigentümer. Für ETW-Investoren sind Beschlüsse, Kostenverteilung, Rücklagen und Zustand des Gemeinschaftseigentums zentrale Risikofaktoren.","url":"/lexikon/weg/","keywords":["weg","wohnungseigentümergemeinschaft.","bezeichnet","nach","kontext","wohnungseigentumsgesetz","gemeinschaft","wohnungseigentümer.","etw-investoren","beschlüsse","kostenverteilung","rücklagen","zustand","gemeinschaftseigentums","zentrale","risikofaktoren."]},{"kind":"lexicon","id":"werbungskosten","title":"Werbungskosten","category":"Steuern","summary":"Aufwendungen zur Erwerbung, Sicherung und Erhaltung steuerpflichtiger Einnahmen.","answer":"Aufwendungen zur Erwerbung, Sicherung und Erhaltung steuerpflichtiger Einnahmen. Werbungskosten sind Aufwendungen zur Erwerbung, Sicherung und Erhaltung steuerpflichtiger Einnahmen. Bei Vermietung können dazu je nach Sachverhalt etwa Schuldzinsen, Verwaltung oder bestimmte Erhaltungsaufwendungen gehören; Tilgung zählt nicht dazu.","url":"/lexikon/werbungskosten/","keywords":["werbungskosten","aufwendungen","zur","erwerbung","sicherung","erhaltung","steuerpflichtiger","einnahmen.","vermietung","können","dazu","nach","sachverhalt","etwa","schuldzinsen","verwaltung","bestimmte","erhaltungsaufwendungen","gehören","tilgung","zählt","dazu."]},{"kind":"lexicon","id":"wertsteigerung","title":"Wertsteigerung","category":"Immobilienkauf","summary":"Zunahme des Marktwerts; keine garantierte Größe.","answer":"Zunahme des Marktwerts; keine garantierte Größe. Wertsteigerung ist die Zunahme des Marktwerts über die Zeit. Sie ist kein garantierter Cashflow und sollte in Investmentrechnungen als Szenario statt als sichere Renditekomponente behandelt werden.","url":"/lexikon/wertsteigerung/","keywords":["wertsteigerung","zunahme","marktwerts","keine","garantierte","größe.","über","zeit.","sie","kein","garantierter","cashflow","sollte","investmentrechnungen","szenario","statt","sichere","renditekomponente","behandelt","werden."]},{"kind":"lexicon","id":"wirtschaftsplan","title":"Wirtschaftsplan","category":"Immobilienkauf","summary":"Plan der WEG zu Einnahmen, Ausgaben und Vorschüssen.","answer":"Plan der WEG zu Einnahmen, Ausgaben und Vorschüssen. Der Wirtschaftsplan der WEG enthält die voraussichtlichen Einnahmen/Ausgaben und Vorschüsse der Eigentümer. Für Kapitalanleger ist die Aufteilung in umlagefähige Kosten, nicht umlagefähige Kosten und Rücklagenzuführung entscheidend.","url":"/lexikon/wirtschaftsplan/","keywords":["wirtschaftsplan","plan","weg","einnahmen","ausgaben","vorschüssen.","enthält","voraussichtlichen","einnahmen/ausgaben","vorschüsse","eigentümer.","kapitalanleger","aufteilung","umlagefähige","kosten","rücklagenzuführung","entscheidend."]},{"kind":"lexicon","id":"wohnflache","title":"Wohnfläche","category":"Immobilienkauf","summary":"Nach einem Regelwerk ermittelte anrechenbare Fläche.","answer":"Nach einem Regelwerk ermittelte anrechenbare Fläche. Wohnfläche ist die nach dem anwendbaren Regelwerk anrechenbare Fläche einer Wohnung. Nach WoFlV zählen unter anderem Keller/Garagen grundsätzlich nicht; Balkone/Terrassen werden regelmäßig nur anteilig und Dachschrägen abhängig von der lichten Höhe berücksichtigt.","url":"/lexikon/wohnflache/","keywords":["wohnfläche","nach","regelwerk","ermittelte","anrechenbare","fläche.","anwendbaren","fläche","wohnung.","woflv","zählen","unter","anderem","keller/garagen","grundsätzlich","balkone/terrassen","regelmäßig","anteilig","dachschrägen","abhängig","lichten","höhe","berücksichtigt."]},{"kind":"lexicon","id":"wohnrecht","title":"Wohnrecht","category":"Immobilienkauf","summary":"Recht, Räume zu Wohnzwecken zu nutzen.","answer":"Recht, Räume zu Wohnzwecken zu nutzen. Ein dingliches Wohnrecht sichert dem Berechtigten die Nutzung bestimmter Räume. Es kann den wirtschaftlichen Wert und die freie Verfügbarkeit einer Immobilie erheblich einschränken.","url":"/lexikon/wohnrecht/","keywords":["wohnrecht","recht","räume","wohnzwecken","nutzen.","dingliches","sichert","berechtigten","nutzung","bestimmter","räume.","kann","wirtschaftlichen","wert","freie","verfügbarkeit","immobilie","erheblich","einschränken."]},{"kind":"lexicon","id":"zins","title":"Zins","category":"Finanzierung","summary":"Preis für die zeitweise Überlassung von Kapital.","answer":"Preis für die zeitweise Überlassung von Kapital. Zins ist der Preis für die zeitweise Überlassung von Kapital. Bei Immobilienfinanzierungen ist zwischen Sollzins, effektivem Jahreszins, Zinsbindung und tatsächlicher Zinsbelastung auf die fallende Restschuld zu unterscheiden.","url":"/lexikon/zins/","keywords":["zins","preis","zeitweise","überlassung","kapital.","immobilienfinanzierungen","zwischen","sollzins","effektivem","jahreszins","zinsbindung","tatsächlicher","zinsbelastung","fallende","restschuld","unterscheiden."]},{"kind":"lexicon","id":"zinsanderungsrisiko","title":"Zinsänderungsrisiko","category":"Finanzierung","summary":"Risiko höherer Kosten bei künftiger Zinsanpassung.","answer":"Risiko höherer Kosten bei künftiger Zinsanpassung. Zinsänderungsrisiko ist das Risiko, dass die Anschlussfinanzierung nach Ende der Zinsbindung zu höheren Konditionen erfolgt. Maßgeblich ist die Restschuld zum Anschlusszeitpunkt.","url":"/lexikon/zinsanderungsrisiko/","keywords":["zinsänderungsrisiko","risiko","höherer","kosten","künftiger","zinsanpassung.","anschlussfinanzierung","nach","ende","zinsbindung","höheren","konditionen","erfolgt.","maßgeblich","restschuld","zum","anschlusszeitpunkt."]},{"kind":"lexicon","id":"zinsbindung","title":"Zinsbindung","category":"Finanzierung","summary":"Zeitraum, für den der Sollzins fest vereinbart ist.","answer":"Zeitraum, für den der Sollzins fest vereinbart ist. Die Zinsbindung ist der Zeitraum, in dem der vereinbarte Sollzins unverändert gilt. Eine längere Bindung erhöht Planungssicherheit, kann aber einen höheren Anfangszins bedeuten.","url":"/lexikon/zinsbindung/","keywords":["zinsbindung","zeitraum","sollzins","fest","vereinbart","ist.","vereinbarte","unverändert","gilt.","längere","bindung","erhöht","planungssicherheit","kann","aber","höheren","anfangszins","bedeuten."]},{"kind":"lexicon","id":"zinsdeckungsgrad","title":"Zinsdeckungsgrad","category":"Finanzierung","summary":"Verhältnis von Ergebnisgröße zu Zinsaufwand.","answer":"Verhältnis von Ergebnisgröße zu Zinsaufwand. Der Zinsdeckungsgrad misst, wie oft eine definierte Ergebnisgröße den reinen Zinsaufwand deckt. Anders als der DSCR berücksichtigt er typischerweise nicht die Tilgung.","url":"/lexikon/zinsdeckungsgrad/","keywords":["zinsdeckungsgrad","verhältnis","ergebnisgröße","zinsaufwand.","misst","oft","definierte","reinen","zinsaufwand","deckt.","anders","dscr","berücksichtigt","typischerweise","tilgung."]},{"kind":"lexicon","id":"zinseszins","title":"Zinseszins","category":"Finanzierung","summary":"Verzinsung bereits gutgeschriebener Zinsen.","answer":"Verzinsung bereits gutgeschriebener Zinsen. Zinseszins entsteht, wenn nicht nur das Anfangskapital, sondern auch bereits gutgeschriebene Zinsen weiter verzinst werden. Er ist besonders bei langfristigem Vermögensaufbau und Opportunitätskosten relevant.","url":"/lexikon/zinseszins/","keywords":["zinseszins","verzinsung","bereits","gutgeschriebener","zinsen.","entsteht","wenn","anfangskapital","sondern","gutgeschriebene","zinsen","weiter","verzinst","werden.","besonders","langfristigem","vermögensaufbau","opportunitätskosten","relevant."]},{"kind":"lexicon","id":"zwangsversteigerung","title":"Zwangsversteigerung","category":"Immobilienkauf","summary":"Gerichtliches Verfahren zur Verwertung einer Immobilie.","answer":"Gerichtliches Verfahren zur Verwertung einer Immobilie. Zwangsversteigerung ist ein gerichtliches Verwertungsverfahren. Erwerber müssen Gutachten, Grundbuch, bestehenbleibende Rechte, Sicherheitsleistung und eingeschränkte Gewährleistung besonders sorgfältig prüfen.","url":"/lexikon/zwangsversteigerung/","keywords":["zwangsversteigerung","gerichtliches","verfahren","zur","verwertung","immobilie.","verwertungsverfahren.","erwerber","müssen","gutachten","grundbuch","bestehenbleibende","rechte","sicherheitsleistung","eingeschränkte","gewährleistung","besonders","sorgfältig","prüfen."]},{"kind":"lexicon","id":"zweckentfremdung","title":"Zweckentfremdung","category":"Immobilienkauf","summary":"Nutzung von Wohnraum zu anderen als Wohnzwecken unter rechtlichen Einschränkungen.","answer":"Nutzung von Wohnraum zu anderen als Wohnzwecken unter rechtlichen Einschränkungen. Zweckentfremdung bezeichnet die Nutzung von Wohnraum zu anderen Zwecken, etwa gewerblicher Kurzzeitvermietung, wenn lokale Vorschriften dies beschränken oder genehmigungspflichtig machen. Regelungen sind kommunal beziehungsweise landesrechtlich unterschiedlich.","url":"/lexikon/zweckentfremdung/","keywords":["zweckentfremdung","nutzung","wohnraum","anderen","wohnzwecken","unter","rechtlichen","einschränkungen.","bezeichnet","zwecken","etwa","gewerblicher","kurzzeitvermietung","wenn","lokale","vorschriften","dies","beschränken","genehmigungspflichtig","machen.","regelungen","kommunal","beziehungsweise","landesrechtlich","unterschiedlich."]}];
